function groupCount(items, keyFn) {
  const map = {};
  (items || []).forEach((it) => { const k = keyFn(it) || 'Non renseigné'; map[k] = (map[k] || 0) + 1; });
  return Object.entries(map).map(([name, value]) => ({ name, value }));
}
