function HaccpStepsSection({ studyId, steps, usersQ, onChanged }) {
  const C = useTheme();
  const [showForm, setShowForm] = useState(false);
  const [editingStep, setEditingStep] = useState(null);
  const ordered = [...steps].sort((a, b) => a.ordre - b.ordre);
  async function move(idx, dir) {
    const j = idx + dir;
    if (j < 0 || j >= ordered.length) return;
    const ids = ordered.map((s) => s.id);
    [ids[idx], ids[j]] = [ids[j], ids[idx]];
    try { await api.post(`/haccp/studies/${studyId}/steps/reorder`, { ids }); onChanged(); }
    catch (err) { alert(err.message); }
  }
  async function del(step) { await confirmAndDelete(step.nom, `/haccp/steps/${step.id}`, onChanged); }
  return (
    <div>
      {(showForm || editingStep) && <HaccpStepFormModal studyId={studyId} record={editingStep} usersQ={usersQ} onClose={() => { setShowForm(false); setEditingStep(null); }} onSaved={() => { setShowForm(false); setEditingStep(null); onChanged(); }} />}
      <div className="flex items-center justify-between mb-2">
        <p className="text-sm font-semibold" style={{ color: C.text }}>Diagramme de flux ({ordered.length} étape(s))</p>
        <button onClick={() => setShowForm(true)} className="text-xs px-2 py-1 rounded-lg" style={{ backgroundColor: C.green, color: '#052e1f' }}>+ Ajouter une étape</button>
      </div>
      {ordered.length
        ? <div className="space-y-1.5">{ordered.map((s, i) => (
            <div key={s.id} className="flex items-center justify-between p-2.5 rounded-lg gap-2" style={{ backgroundColor: C.cardAlt }}>
              <div className="flex items-center gap-2 min-w-0">
                <span className="text-xs font-bold px-2 py-1 rounded-full flex-shrink-0" style={{ backgroundColor: `${C.blue}22`, color: C.blue }}>{s.numero ?? i + 1}</span>
                <div className="min-w-0">
                  <p className="text-sm font-medium truncate" style={{ color: C.text }}>{s.nom}</p>
                  <p className="text-[11px] truncate" style={{ color: C.textMuted }}>{[s.zone, s.equipement].filter(Boolean).join(' · ') || '—'}{s.hazards ? ` · ${s.hazards.length} danger(s)` : ''}</p>
                </div>
              </div>
              <div className="flex items-center gap-1 flex-shrink-0">
                <button onClick={() => move(i, -1)} disabled={i === 0} className="text-xs px-1.5 py-1 rounded" style={{ backgroundColor: C.card, border: `1px solid ${C.border}`, color: C.text, opacity: i === 0 ? 0.4 : 1 }}>▲</button>
                <button onClick={() => move(i, 1)} disabled={i === ordered.length - 1} className="text-xs px-1.5 py-1 rounded" style={{ backgroundColor: C.card, border: `1px solid ${C.border}`, color: C.text, opacity: i === ordered.length - 1 ? 0.4 : 1 }}>▼</button>
                <button onClick={() => setEditingStep(s)} className="text-[11px] px-2 py-1 rounded-lg" style={{ backgroundColor: C.card, border: `1px solid ${C.border}`, color: C.text }}>Modifier</button>
                <button onClick={() => del(s)} className="text-[11px]" style={{ color: C.red }}>Supprimer</button>
              </div>
            </div>
          ))}</div>
        : <p className="text-sm text-center py-6" style={{ color: C.textMuted }}>Aucune étape définie pour le moment</p>}
    </div>
  );
}

function HaccpHazardFormModal({ stepId, record, onClose, onSaved }) {
  const C = useTheme();
  const editing = !!record;
  const [form, setForm] = useState({
    type: record?.type || 'BIOLOGIQUE', libelle: record?.libelle || '', origine: record?.origine || '',
    gravite: record?.gravite ?? '', probabilite: record?.probabilite ?? '', niveauMaitrise: record?.niveauMaitrise ?? '',
    justification: record?.justification || '', mesuresExistantes: record?.mesuresExistantes || '', mesuresSupplementaires: record?.mesuresSupplementaires || '',
  });
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState(null);
  async function submit(e) {
    e.preventDefault();
    if (!form.libelle.trim()) { setError('Le libellé du danger est obligatoire.'); return; }
    setSaving(true); setError(null);
    try {
      const payload = { ...form, gravite: form.gravite === '' ? undefined : Number(form.gravite), probabilite: form.probabilite === '' ? undefined : Number(form.probabilite), niveauMaitrise: form.niveauMaitrise === '' ? undefined : Number(form.niveauMaitrise) };
      if (editing) await api.patch(`/haccp/hazards/${record.id}`, payload);
      else await api.post(`/haccp/steps/${stepId}/hazards`, payload);
      onSaved();
    } catch (err) { setError(err.message); }
    setSaving(false);
  }
  return (
    <Modal title={editing ? 'Modifier le danger' : 'Nouveau danger identifié'} onClose={onClose}>
      <form onSubmit={submit}>
        <div className="grid grid-cols-2 gap-3">
          <FormField label="Type *">
            <select value={form.type} onChange={(e) => setForm({ ...form, type: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)}>
              {Object.entries(HACCP_HAZARD_TYPE_LABELS).map(([v, l]) => <option key={v} value={v}>{l}</option>)}
            </select>
          </FormField>
          <FormField label="Libellé *"><input value={form.libelle} onChange={(e) => setForm({ ...form, libelle: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
        </div>
        <FormField label="Origine"><input value={form.origine} onChange={(e) => setForm({ ...form, origine: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
        <div className="grid grid-cols-3 gap-3">
          <FormField label="Gravité (1-5)"><input type="number" min="1" max="5" value={form.gravite} onChange={(e) => setForm({ ...form, gravite: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
          <FormField label="Probabilité (1-5)"><input type="number" min="1" max="5" value={form.probabilite} onChange={(e) => setForm({ ...form, probabilite: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
          <FormField label="Niveau de maîtrise"><input type="number" value={form.niveauMaitrise} onChange={(e) => setForm({ ...form, niveauMaitrise: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
        </div>
        {editing && record.niveauRisque && <p className="text-xs mb-3" style={{ color: haccpRiskColor(C, record.niveauRisque) }}>Niveau de risque calculé automatiquement : {HACCP_RISK_LEVEL_LABELS[record.niveauRisque] || record.niveauRisque}</p>}
        <FormField label="Justification"><textarea value={form.justification} onChange={(e) => setForm({ ...form, justification: e.target.value })} rows={2} className="w-full px-3 py-2 rounded-lg text-sm outline-none resize-none" style={inputStyle(C)} /></FormField>
        <FormField label="Mesures existantes"><textarea value={form.mesuresExistantes} onChange={(e) => setForm({ ...form, mesuresExistantes: e.target.value })} rows={2} className="w-full px-3 py-2 rounded-lg text-sm outline-none resize-none" style={inputStyle(C)} /></FormField>
        <FormField label="Mesures supplémentaires"><textarea value={form.mesuresSupplementaires} onChange={(e) => setForm({ ...form, mesuresSupplementaires: e.target.value })} rows={2} className="w-full px-3 py-2 rounded-lg text-sm outline-none resize-none" style={inputStyle(C)} /></FormField>
        {error && <p className="text-xs mb-3" style={{ color: C.red }}>{error}</p>}
        <button type="submit" disabled={saving} className="w-full py-2.5 rounded-lg text-sm font-medium" style={{ backgroundColor: C.blue, color: '#fff', opacity: saving ? 0.7 : 1 }}>{saving ? 'Enregistrement…' : editing ? 'Enregistrer les modifications' : 'Ajouter le danger'}</button>
      </form>
    </Modal>
  );
}

function HaccpCcpFormModal({ hazardId, record, usersQ, onClose, onSaved }) {
  const C = useTheme();
  const editing = !!record;
  const [form, setForm] = useState({
    type: record?.type || 'CCP', dangerMaitrise: record?.dangerMaitrise || '', causeDanger: record?.causeDanger || '',
    mesureMaitrise: record?.mesureMaitrise || '', limiteCritique: record?.limiteCritique || '', critereAcceptation: record?.critereAcceptation || '',
    parametre: record?.parametre || '', unite: record?.unite || '', methode: record?.methode || '', instrument: record?.instrument || '',
    frequence: record?.frequence || '', responsableId: record?.responsableId || '', enregistrementAssocie: record?.enregistrementAssocie || '',
    actionImmediate: record?.actionImmediate || '', active: record?.active ?? true,
  });
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState(null);
  async function submit(e) {
    e.preventDefault();
    setSaving(true); setError(null);
    try {
      const payload = { ...form, responsableId: form.responsableId || null };
      if (editing) await api.patch(`/haccp/ccps/${record.id}`, payload);
      else await api.post(`/haccp/hazards/${hazardId}/ccps`, payload);
      onSaved();
    } catch (err) { setError(err.message); }
    setSaving(false);
  }
  return (
    <Modal title={editing ? 'Modifier la fiche CCP/CP' : 'Nouveau CCP/CP'} onClose={onClose} wide>
      <form onSubmit={submit}>
        {editing && <p className="text-xs mb-3" style={{ color: C.textMuted }}>Référence : <strong style={{ color: C.text }}>{record.reference}</strong> (générée automatiquement, non modifiable)</p>}
        <div className="grid grid-cols-2 gap-3">
          <FormField label="Type">
            <select value={form.type} onChange={(e) => setForm({ ...form, type: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)}>
              <option value="CCP">CCP — point critique de maîtrise</option><option value="CP">CP — point de vigilance</option>
            </select>
          </FormField>
          <FormField label="Danger maîtrisé"><input value={form.dangerMaitrise} onChange={(e) => setForm({ ...form, dangerMaitrise: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
        </div>
        <FormField label="Cause du danger"><input value={form.causeDanger} onChange={(e) => setForm({ ...form, causeDanger: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
        <FormField label="Mesure de maîtrise"><textarea value={form.mesureMaitrise} onChange={(e) => setForm({ ...form, mesureMaitrise: e.target.value })} rows={2} className="w-full px-3 py-2 rounded-lg text-sm outline-none resize-none" style={inputStyle(C)} /></FormField>
        <div className="grid grid-cols-2 gap-3">
          <FormField label="Limite critique"><input value={form.limiteCritique} onChange={(e) => setForm({ ...form, limiteCritique: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
          <FormField label="Critère d'acceptation"><input value={form.critereAcceptation} onChange={(e) => setForm({ ...form, critereAcceptation: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
        </div>
        <div className="grid grid-cols-3 gap-3">
          <FormField label="Paramètre"><input value={form.parametre} onChange={(e) => setForm({ ...form, parametre: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
          <FormField label="Unité"><input value={form.unite} onChange={(e) => setForm({ ...form, unite: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
          <FormField label="Fréquence"><input value={form.frequence} onChange={(e) => setForm({ ...form, frequence: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
        </div>
        <div className="grid grid-cols-2 gap-3">
          <FormField label="Méthode"><input value={form.methode} onChange={(e) => setForm({ ...form, methode: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
          <FormField label="Instrument"><input value={form.instrument} onChange={(e) => setForm({ ...form, instrument: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
        </div>
        <FormField label="Responsable">
          <select value={form.responsableId} onChange={(e) => setForm({ ...form, responsableId: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)}>
            <option value="">—</option>{(usersQ.data || []).map((u) => <option key={u.id} value={u.id}>{u.firstName} {u.lastName}</option>)}
          </select>
        </FormField>
        <FormField label="Enregistrement associé"><input value={form.enregistrementAssocie} onChange={(e) => setForm({ ...form, enregistrementAssocie: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
        <FormField label="Action immédiate en cas d'écart"><textarea value={form.actionImmediate} onChange={(e) => setForm({ ...form, actionImmediate: e.target.value })} rows={2} className="w-full px-3 py-2 rounded-lg text-sm outline-none resize-none" style={inputStyle(C)} /></FormField>
        <label className="flex items-center gap-2 text-xs mb-3" style={{ color: C.textMuted }}>
          <input type="checkbox" checked={form.active} onChange={(e) => setForm({ ...form, active: e.target.checked })} /> Actif
        </label>
        {error && <p className="text-xs mb-3" style={{ color: C.red }}>{error}</p>}
        <button type="submit" disabled={saving} className="w-full py-2.5 rounded-lg text-sm font-medium" style={{ backgroundColor: C.blue, color: '#fff', opacity: saving ? 0.7 : 1 }}>{saving ? 'Enregistrement…' : editing ? 'Enregistrer les modifications' : 'Créer la fiche CCP/CP'}</button>
      </form>
    </Modal>
  );
}

function HaccpHazardsSection({ studyId, steps, usersQ, onChanged }) {
  const C = useTheme();
  const [openStepId, setOpenStepId] = useState(null);
  const [addingToStep, setAddingToStep] = useState(null);
  const [editingHazard, setEditingHazard] = useState(null);
  const [addingCcpFor, setAddingCcpFor] = useState(null);
  const ordered = [...steps].sort((a, b) => a.ordre - b.ordre);
  async function delHazard(h) { await confirmAndDelete(h.libelle, `/haccp/hazards/${h.id}`, onChanged); }
  return (
    <div>
      {addingToStep && <HaccpHazardFormModal stepId={addingToStep} onClose={() => setAddingToStep(null)} onSaved={() => { setAddingToStep(null); onChanged(); }} />}
      {editingHazard && <HaccpHazardFormModal stepId={editingHazard.stepId} record={editingHazard} onClose={() => setEditingHazard(null)} onSaved={() => { setEditingHazard(null); onChanged(); }} />}
      {addingCcpFor && <HaccpCcpFormModal hazardId={addingCcpFor} usersQ={usersQ} onClose={() => setAddingCcpFor(null)} onSaved={() => { setAddingCcpFor(null); onChanged(); }} />}
      {ordered.length === 0 && <p className="text-sm text-center py-6" style={{ color: C.textMuted }}>Définissez d'abord le diagramme de flux pour pouvoir analyser les dangers par étape</p>}
      <div className="space-y-2">
        {ordered.map((s) => {
          const open = openStepId === s.id;
          const hazards = s.hazards || [];
          return (
            <div key={s.id} className="rounded-lg" style={{ backgroundColor: C.cardAlt, border: `1px solid ${C.border}` }}>
              <div className="flex items-center justify-between p-2.5 cursor-pointer" onClick={() => setOpenStepId(open ? null : s.id)}>
                <span className="text-sm font-medium" style={{ color: C.text }}>{s.numero ? `${s.numero}. ` : ''}{s.nom} <span className="text-xs" style={{ color: C.textMuted }}>({hazards.length} danger(s))</span></span>
                <span className="text-xs" style={{ color: C.textMuted }}>{open ? '▲' : '▼'}</span>
              </div>
              {open && (
                <div className="p-2.5 pt-0 space-y-2">
                  <button onClick={() => setAddingToStep(s.id)} className="text-xs px-2 py-1 rounded-lg" style={{ backgroundColor: C.green, color: '#052e1f' }}>+ Ajouter un danger</button>
                  {hazards.map((h) => (
                    <div key={h.id} className="p-2.5 rounded-lg" style={{ backgroundColor: C.card }}>
                      <div className="flex items-start justify-between gap-2 flex-wrap">
                        <div className="min-w-0">
                          <div className="flex items-center gap-2 flex-wrap">
                            <span className="text-xs font-semibold" style={{ color: C.text }}>{HACCP_HAZARD_TYPE_LABELS[h.type] || h.type}</span>
                            <span className="text-sm" style={{ color: C.text }}>{h.libelle}</span>
                            {h.niveauRisque && <span className="text-[10px] px-1.5 py-0.5 rounded-full" style={{ backgroundColor: `${haccpRiskColor(C, h.niveauRisque)}22`, color: haccpRiskColor(C, h.niveauRisque) }}>{HACCP_RISK_LEVEL_LABELS[h.niveauRisque] || h.niveauRisque}</span>}
                          </div>
                          {h.mesuresExistantes && <p className="text-[11px] mt-1" style={{ color: C.textMuted }}>Mesures existantes : {h.mesuresExistantes}</p>}
                          {(h.ccps || []).length > 0 && <p className="text-[11px] mt-1" style={{ color: C.blue }}>{h.ccps.length} CCP/CP associé(s) : {h.ccps.map((c) => c.reference).join(', ')}</p>}
                        </div>
                        <div className="flex gap-2 flex-shrink-0">
                          <button onClick={() => setAddingCcpFor(h.id)} className="text-[11px] px-2 py-1 rounded-lg" style={{ backgroundColor: C.blue, color: '#fff' }}>+ CCP/CP</button>
                          <button onClick={() => setEditingHazard({ ...h, stepId: s.id })} className="text-[11px] px-2 py-1 rounded-lg" style={{ backgroundColor: C.card, border: `1px solid ${C.border}`, color: C.text }}>Modifier</button>
                          <button onClick={() => delHazard(h)} className="text-[11px]" style={{ color: C.red }}>Supprimer</button>
                        </div>
                      </div>
                    </div>
                  ))}
                  {hazards.length === 0 && <p className="text-xs text-center py-3" style={{ color: C.textMuted }}>Aucun danger identifié pour cette étape</p>}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

function HaccpCcpDetailModal({ ccp, usersQ, onClose, onChanged }) {
  const C = useTheme();
  const [editing, setEditing] = useState(false);
  async function del() { await confirmAndDelete(ccp.reference, `/haccp/ccps/${ccp.id}`, () => { onChanged(); onClose(); }); }
  if (editing) return <HaccpCcpFormModal record={ccp} hazardId={ccp.hazardId} usersQ={usersQ} onClose={() => setEditing(false)} onSaved={() => { setEditing(false); onChanged(); }} />;
  return (
    <Modal title={`${ccp.reference} — ${ccp.dangerMaitrise || 'Fiche CCP/CP'}`} onClose={onClose} wide>
      <div className="flex items-center justify-between mb-3">
        <span className="text-xs px-2 py-1 rounded-full" style={{ backgroundColor: `${C.blue}22`, color: C.blue }}>{ccp.type === 'CCP' ? 'Point critique de maîtrise' : 'Point de vigilance'}</span>
        <StatusChip statut={ccp.active ? 'Conforme' : 'Non conforme'} />
      </div>
      <div className="flex gap-2 mb-4">
        <button onClick={() => setEditing(true)} className="text-xs px-2 py-1.5 rounded-lg" style={{ backgroundColor: C.cardAlt, border: `1px solid ${C.border}`, color: C.text }}>Modifier</button>
        <button onClick={del} className="text-xs px-2 py-1.5 rounded-lg" style={{ backgroundColor: `${C.red}22`, color: C.red }}>Supprimer</button>
      </div>
      <div className="grid grid-cols-2 gap-4 mb-5 text-sm">
        {ccp.causeDanger && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Cause du danger</p><p style={{ color: C.text }}>{ccp.causeDanger}</p></div>}
        {ccp.mesureMaitrise && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Mesure de maîtrise</p><p style={{ color: C.text }}>{ccp.mesureMaitrise}</p></div>}
        {ccp.limiteCritique && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Limite critique</p><p style={{ color: C.text }}>{ccp.limiteCritique}</p></div>}
        {ccp.critereAcceptation && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Critère d'acceptation</p><p style={{ color: C.text }}>{ccp.critereAcceptation}</p></div>}
        {ccp.parametre && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Paramètre surveillé</p><p style={{ color: C.text }}>{ccp.parametre}{ccp.unite ? ` (${ccp.unite})` : ''}</p></div>}
        {ccp.frequence && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Fréquence</p><p style={{ color: C.text }}>{ccp.frequence}</p></div>}
        {ccp.methode && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Méthode</p><p style={{ color: C.text }}>{ccp.methode}</p></div>}
        {ccp.instrument && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Instrument</p><p style={{ color: C.text }}>{ccp.instrument}</p></div>}
        {ccp.enregistrementAssocie && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Enregistrement associé</p><p style={{ color: C.text }}>{ccp.enregistrementAssocie}</p></div>}
        {ccp.actionImmediate && <div className="col-span-2"><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Action immédiate en cas d'écart</p><p style={{ color: C.text }}>{ccp.actionImmediate}</p></div>}
      </div>
      <DocumentLinksPanel sourceModule="HACCP_CCP" sourceEntityId={ccp.id} />
    </Modal>
  );
}

function HaccpCcpsSection({ studyId, usersQ }) {
  const C = useTheme();
  const ccpsQ = useCollection(`/haccp/studies/${studyId}/ccps`);
  const [selected, setSelected] = useState(null);
  if (ccpsQ.loading) return <LoadingPanel />;
  if (ccpsQ.error) return <ErrorPanel message={ccpsQ.error} onRetry={ccpsQ.reload} />;
  const list = ccpsQ.data || [];
  return (
    <div>
      {selected && <HaccpCcpDetailModal ccp={selected} usersQ={usersQ} onClose={() => setSelected(null)} onChanged={ccpsQ.reload} />}
      <p className="text-sm font-semibold mb-2" style={{ color: C.text }}>CCP / CP de l'étude ({list.length})</p>
      {list.length
        ? <DataTable columns={['Référence', 'Type', 'Étape', 'Danger maîtrisé', 'Limite critique', 'Statut']}
            rows={list.map((c) => [c.reference, c.type, c.step?.nom || '—', c.dangerMaitrise || '—', c.limiteCritique || '—', <StatusChip statut={c.active ? 'Conforme' : 'Non conforme'} />])}
            onRowClick={(i) => setSelected(list[i])} />
        : <p className="text-sm text-center py-6" style={{ color: C.textMuted }}>Aucun CCP/CP défini — ajoutez-en depuis l'onglet « Analyse des dangers »</p>}
    </div>
  );
}

function HaccpRevisionsSection({ study, onRevise }) {
  const C = useTheme();
  const revisions = study.revisions || [];
  return (
    <div>
      <div className="flex items-center justify-between mb-2">
        <p className="text-sm font-semibold" style={{ color: C.text }}>Historique des révisions ({revisions.length})</p>
        <button onClick={onRevise} className="text-xs px-2 py-1 rounded-lg" style={{ backgroundColor: C.green, color: '#052e1f' }}>+ Réviser le plan</button>
      </div>
      {study.prochaineRevision && <p className="text-xs mb-3" style={{ color: C.textMuted }}>Prochaine révision prévue le {new Date(study.prochaineRevision).toLocaleDateString('fr-FR')}</p>}
      {revisions.length
        ? <DataTable columns={['Date', 'Version', 'Déclencheur', 'Description']}
            rows={revisions.map((r) => [new Date(r.date).toLocaleDateString('fr-FR'), r.version, r.declencheur, r.description || '—'])} />
        : <p className="text-sm text-center py-6" style={{ color: C.textMuted }}>Aucune révision enregistrée pour le moment</p>}
    </div>
  );
}

function HaccpStudyDetailModal({ studyId, onClose, onChanged }) {
  const C = useTheme();
  const detailQ = useCollection(`/haccp/studies/${studyId}`);
  const usersQ = useCollection('/users');
  const [tab, setTab] = useState('info');
  const [editing, setEditing] = useState(false);
  const [showRevise, setShowRevise] = useState(false);
  const [busy, setBusy] = useState(false);
  if (detailQ.loading) return <Modal title="Étude HACCP" onClose={onClose} wide><LoadingPanel /></Modal>;
  if (detailQ.error || !detailQ.data) return <Modal title="Étude HACCP" onClose={onClose} wide><ErrorPanel message={detailQ.error} onRetry={detailQ.reload} /></Modal>;
  const study = detailQ.data;
  function reload() { detailQ.reload(); onChanged(); }
  async function validate() {
    setBusy(true);
    try { await api.post(`/haccp/studies/${study.id}/validate`, {}); reload(); }
    catch (err) { alert(err.message); }
    setBusy(false);
  }
  async function del() {
    if (!window.confirm(`Supprimer définitivement l'étude « ${study.name} » ? Cette action est irréversible.`)) return;
    setBusy(true);
    try { await api.del(`/haccp/studies/${study.id}`); onChanged(); onClose(); }
    catch (err) { alert(err.message); }
    setBusy(false);
  }
  if (editing) return <HaccpStudyFormModal record={study} onClose={() => setEditing(false)} onCreated={() => { setEditing(false); reload(); }} />;
  if (showRevise) return <HaccpReviseModal study={study} onClose={() => setShowRevise(false)} onSaved={() => { setShowRevise(false); reload(); }} />;
  return (
    <Modal title={`${study.code} — ${study.name}`} onClose={onClose} wide>
      <div className="flex items-center justify-between mb-3 flex-wrap gap-2">
        <p className="text-xs" style={{ color: C.textMuted }}>Version {study.version} · Créée le {new Date(study.dateCreation).toLocaleDateString('fr-FR')}{study.dateDerniereRevision ? ` · Dernière révision le ${new Date(study.dateDerniereRevision).toLocaleDateString('fr-FR')}` : ''}</p>
        <StatusChip statut={HACCP_STUDY_STATUS_LABELS[study.status] || study.status} />
      </div>
      <div className="flex gap-2 flex-wrap mb-4">
        <button onClick={() => setEditing(true)} className="text-xs px-2 py-1.5 rounded-lg" style={{ backgroundColor: C.cardAlt, border: `1px solid ${C.border}`, color: C.text }}>Modifier</button>
        {(study.status === 'BROUILLON' || study.status === 'EN_VALIDATION') && <button disabled={busy} onClick={validate} className="text-xs px-2 py-1.5 rounded-lg font-medium" style={{ backgroundColor: C.blue, color: '#fff' }}>{study.status === 'BROUILLON' ? 'Soumettre pour validation' : 'Valider'}</button>}
        <button onClick={() => setShowRevise(true)} className="text-xs px-2 py-1.5 rounded-lg" style={{ backgroundColor: C.cardAlt, border: `1px solid ${C.border}`, color: C.text }}>Réviser</button>
        <button disabled={busy} onClick={del} className="text-xs px-2 py-1.5 rounded-lg" style={{ backgroundColor: `${C.red}22`, color: C.red }}>Supprimer</button>
      </div>
      <div className="flex flex-wrap gap-2 mb-4">
        {[['info', 'Info générale'], ['equipe', 'Équipe'], ['diagramme', 'Diagramme de flux'], ['dangers', 'Analyse des dangers'], ['ccp', 'CCP / CP'], ['revisions', 'Révisions']].map(([id, label]) => (
          <button key={id} onClick={() => setTab(id)} className="px-3 py-1.5 rounded-lg text-xs font-medium" style={{ backgroundColor: tab === id ? C.blue : 'transparent', color: tab === id ? '#fff' : C.textMuted }}>{label}</button>
        ))}
      </div>
      {tab === 'info' && (
        <div className="space-y-4">
          <div className="grid grid-cols-2 gap-4 text-sm">
            {study.activite && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Activité</p><p style={{ color: C.text }}>{study.activite}</p></div>}
            {study.atelier && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Atelier</p><p style={{ color: C.text }}>{study.atelier}</p></div>}
            {study.ligne && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Ligne</p><p style={{ color: C.text }}>{study.ligne}</p></div>}
            {study.produit && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Produit</p><p style={{ color: C.text }}>{study.produit}</p></div>}
            {study.categorieProduit && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Catégorie de produit</p><p style={{ color: C.text }}>{study.categorieProduit}</p></div>}
            {study.descriptionProduit && <div className="col-span-2"><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Description du produit</p><p style={{ color: C.text }}>{study.descriptionProduit}</p></div>}
            {study.destination && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Destination</p><p style={{ color: C.text }}>{study.destination}</p></div>}
            {study.consommateurCible && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Consommateur cible</p><p style={{ color: C.text }}>{study.consommateurCible}</p></div>}
            {study.conditionsStockage && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Conditions de stockage</p><p style={{ color: C.text }}>{study.conditionsStockage}</p></div>}
            {study.dureeConservation && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Durée de conservation</p><p style={{ color: C.text }}>{study.dureeConservation}</p></div>}
            {study.modeDistribution && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Mode de distribution</p><p style={{ color: C.text }}>{study.modeDistribution}</p></div>}
          </div>
          <DocumentLinksPanel sourceModule="HACCP" sourceEntityId={study.id} />
        </div>
      )}
      {tab === 'equipe' && <HaccpTeamSection studyId={study.id} team={study.team || []} onChanged={reload} />}
      {tab === 'diagramme' && <HaccpStepsSection studyId={study.id} steps={study.steps || []} usersQ={usersQ} onChanged={reload} />}
      {tab === 'dangers' && <HaccpHazardsSection studyId={study.id} steps={study.steps || []} usersQ={usersQ} onChanged={reload} />}
      {tab === 'ccp' && <HaccpCcpsSection studyId={study.id} usersQ={usersQ} />}
      {tab === 'revisions' && <HaccpRevisionsSection study={study} onRevise={() => setShowRevise(true)} />}
    </Modal>
  );
}

function HaccpEtudesTab() {
  const C = useTheme();
  const studiesQ = useCollection('/haccp/studies');
  const [showForm, setShowForm] = useState(false);
  const [detailId, setDetailId] = useState(null);
  if (studiesQ.loading) return <LoadingPanel />;
  if (studiesQ.error) return <ErrorPanel message={studiesQ.error} onRetry={studiesQ.reload} />;
  const list = studiesQ.data || [];
  return (
    <div className="space-y-4">
      {showForm && <HaccpStudyFormModal onClose={() => setShowForm(false)} onCreated={studiesQ.reload} />}
      {detailId && <HaccpStudyDetailModal studyId={detailId} onClose={() => setDetailId(null)} onChanged={studiesQ.reload} />}
      <div className="flex items-center justify-between">
        <LiveBadge />
        <button onClick={() => setShowForm(true)} className="px-3 py-1.5 rounded-lg text-xs font-medium" style={{ backgroundColor: C.green, color: '#052e1f' }}>+ Nouvelle étude HACCP</button>
      </div>
      <Panel title="Études HACCP" subtitle={`${list.length} étude(s)`}>
        {list.length
          ? <DataTable columns={['Code', 'Nom', 'Produit', 'Version', 'Statut']}
              rows={list.map((s) => [s.code, s.name, s.produit || '—', s.version, <StatusChip statut={HACCP_STUDY_STATUS_LABELS[s.status] || s.status} />])}
              onRowClick={(i) => setDetailId(list[i].id)} />
          : <p className="text-sm text-center py-6" style={{ color: C.textMuted }}>Aucune étude HACCP enregistrée pour le moment</p>}
      </Panel>
    </div>
  );
}

// Ligne d'un relevé de surveillance — LE point le plus important : quand
// nonConformityId est renseigné (créé automatiquement côté serveur pour un
// relevé conforme:false), on affiche immédiatement le lien vers la NC et le
// panneau CapaLinksPanel (sourceModule='HACCP_CCP', sourceEntityId=relevé)
// pour créer l'Action CAPA en un clic, exactement comme pour SAFETY_TALK.
function HaccpMonitoringRow({ record, onChanged }) {
  const C = useTheme();
  const [editingResult, setEditingResult] = useState(false);
  const [form, setForm] = useState(null);
  const ncQ = useCollection(record.nonConformityId ? `/business/non-conformities/${record.nonConformityId}` : null);
  const [busy, setBusy] = useState(false);
  function openEdit() {
    setForm({ valeur: record.valeur ?? '', valeurTexte: record.valeurTexte || '', conforme: record.conforme === true ? 'true' : record.conforme === false ? 'false' : '', commentaire: record.commentaire || '', lotNumero: record.lotNumero || '' });
    setEditingResult(true);
  }
  async function saveResult(e) {
    e.preventDefault();
    setBusy(true);
    try {
      await api.patch(`/haccp/monitoring/${record.id}`, {
        valeur: form.valeur === '' ? undefined : Number(form.valeur), valeurTexte: form.valeurTexte || undefined,
        conforme: form.conforme === '' ? undefined : form.conforme === 'true', commentaire: form.commentaire || undefined,
        lotNumero: form.lotNumero || undefined, dateRealisee: new Date().toISOString(),
      });
      setEditingResult(false); onChanged();
    } catch (err) { alert(err.message); }
    setBusy(false);
  }
  return (
    <div className="p-2.5 rounded-lg" style={{ backgroundColor: C.cardAlt }}>
      <div className="flex items-start justify-between gap-2 flex-wrap">
        <div className="min-w-0">
          <div className="flex items-center gap-2 flex-wrap">
            <span className="text-sm font-medium" style={{ color: C.text }}>{record.datePrevue ? new Date(record.datePrevue).toLocaleString('fr-FR') : 'Sans échéance'}</span>
            <StatusChip statut={HACCP_MONITORING_STATUS_LABELS[record.statut] || record.statut} />
          </div>
          <p className="text-xs mt-1" style={{ color: C.textMuted }}>
            {record.dateRealisee ? `Réalisé le ${new Date(record.dateRealisee).toLocaleString('fr-FR')}` : 'Non réalisé'}
            {record.valeur != null ? ` · valeur : ${record.valeur}` : ''}{record.valeurTexte ? ` · ${record.valeurTexte}` : ''}
            {record.lotNumero ? ` · lot ${record.lotNumero}` : ''}
          </p>
          {record.commentaire && <p className="text-xs mt-0.5" style={{ color: C.textMuted }}>{record.commentaire}</p>}
        </div>
        {!editingResult && <button onClick={openEdit} className="text-[11px] px-2 py-1 rounded-lg flex-shrink-0" style={{ backgroundColor: C.card, border: `1px solid ${C.border}`, color: C.text }}>Saisir le résultat</button>}
      </div>
      {editingResult && (
        <form onSubmit={saveResult} className="mt-2 pt-2 grid grid-cols-2 gap-2" style={{ borderTop: `1px solid ${C.border}` }}>
          <FormField label="Valeur mesurée"><input type="number" step="any" value={form.valeur} onChange={(e) => setForm({ ...form, valeur: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
          <FormField label="Conforme ?">
            <select value={form.conforme} onChange={(e) => setForm({ ...form, conforme: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)}>
              <option value="">—</option><option value="true">Oui</option><option value="false">Non</option>
            </select>
          </FormField>
          <FormField label="Observation"><input value={form.valeurTexte} onChange={(e) => setForm({ ...form, valeurTexte: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
          <FormField label="N° de lot"><input value={form.lotNumero} onChange={(e) => setForm({ ...form, lotNumero: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
          <div className="col-span-2"><FormField label="Commentaire"><textarea value={form.commentaire} onChange={(e) => setForm({ ...form, commentaire: e.target.value })} rows={2} className="w-full px-3 py-2 rounded-lg text-sm outline-none resize-none" style={inputStyle(C)} /></FormField></div>
          <div className="col-span-2 flex gap-2">
            <button type="button" onClick={() => setEditingResult(false)} className="flex-1 py-2 rounded-lg text-xs" style={{ backgroundColor: C.card, border: `1px solid ${C.border}`, color: C.text }}>Annuler</button>
            <button type="submit" disabled={busy} className="flex-1 py-2 rounded-lg text-xs font-medium" style={{ backgroundColor: C.blue, color: '#fff', opacity: busy ? 0.7 : 1 }}>{busy ? '…' : 'Enregistrer le résultat'}</button>
          </div>
        </form>
      )}
      {record.nonConformityId && (
        <div className="mt-2 pt-2" style={{ borderTop: `1px solid ${C.border}` }}>
          <div className="p-2.5 rounded-lg mb-2" style={{ backgroundColor: `${C.red}18`, border: `1px solid ${C.red}40` }}>
            <p className="text-xs font-semibold" style={{ color: C.red }}>⚠ Non-conformité créée automatiquement</p>
            <p className="text-xs mt-0.5" style={{ color: C.text }}>{ncQ.data ? `${ncQ.data.code} — ${ncQ.data.title}` : 'Chargement…'}</p>
          </div>
          <CapaLinksPanel sourceModule="HACCP_CCP" sourceEntityId={record.id} />
        </div>
      )}
    </div>
  );
}

function HaccpMonitoringForm({ ccpId, usersQ, onCreated }) {
  const C = useTheme();
  const empty = { datePrevue: '', dateRealisee: '', valeur: '', valeurTexte: '', conforme: '', lotNumero: '', responsableId: '', commentaire: '', signature: '' };
  const [form, setForm] = useState(empty);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState(null);
  const [justCreated, setJustCreated] = useState(null);
  async function submit(e) {
    e.preventDefault();
    setSaving(true); setError(null); setJustCreated(null);
    try {
      const created = await api.post(`/haccp/ccps/${ccpId}/monitoring`, {
        datePrevue: form.datePrevue ? new Date(form.datePrevue).toISOString() : undefined,
        dateRealisee: form.dateRealisee ? new Date(form.dateRealisee).toISOString() : undefined,
        valeur: form.valeur === '' ? undefined : Number(form.valeur), valeurTexte: form.valeurTexte || undefined,
        conforme: form.conforme === '' ? undefined : form.conforme === 'true',
        lotNumero: form.lotNumero || undefined, responsableId: form.responsableId || undefined,
        commentaire: form.commentaire || undefined, signature: form.signature || undefined,
      });
      setForm(empty); setJustCreated(created); onCreated();
    } catch (err) { setError(err.message); }
    setSaving(false);
  }
  return (
    <div>
      <form onSubmit={submit} className="grid grid-cols-3 gap-3 p-3 rounded-lg mb-3" style={{ backgroundColor: C.cardAlt, border: `1px solid ${C.border}` }}>
        <FormField label="Date/heure prévue"><input type="datetime-local" value={form.datePrevue} onChange={(e) => setForm({ ...form, datePrevue: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
        <FormField label="Valeur mesurée"><input type="number" step="any" value={form.valeur} onChange={(e) => setForm({ ...form, valeur: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
        <FormField label="Conforme ?">
          <select value={form.conforme} onChange={(e) => setForm({ ...form, conforme: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)}>
            <option value="">Non évalué</option><option value="true">Oui</option><option value="false">Non</option>
          </select>
        </FormField>
        <FormField label="Observation"><input value={form.valeurTexte} onChange={(e) => setForm({ ...form, valeurTexte: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
        <FormField label="N° de lot"><input value={form.lotNumero} onChange={(e) => setForm({ ...form, lotNumero: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
        <FormField label="Responsable">
          <select value={form.responsableId} onChange={(e) => setForm({ ...form, responsableId: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)}>
            <option value="">—</option>{(usersQ.data || []).map((u) => <option key={u.id} value={u.id}>{u.firstName} {u.lastName}</option>)}
          </select>
        </FormField>
        <div className="col-span-3"><FormField label="Commentaire"><textarea value={form.commentaire} onChange={(e) => setForm({ ...form, commentaire: e.target.value })} rows={2} className="w-full px-3 py-2 rounded-lg text-sm outline-none resize-none" style={inputStyle(C)} /></FormField></div>
        <div className="col-span-3"><SignaturePad label="Signature de contrôle" value={form.signature} onChange={(v) => setForm({ ...form, signature: v })} /></div>
        {error && <p className="text-xs col-span-3" style={{ color: C.red }}>{error}</p>}
        <button type="submit" disabled={saving} className="col-span-3 py-2.5 rounded-lg text-sm font-medium" style={{ backgroundColor: C.blue, color: '#fff', opacity: saving ? 0.7 : 1 }}>{saving ? 'Enregistrement…' : 'Enregistrer le relevé'}</button>
      </form>
      {justCreated?.nonConformityId && (
        <div className="p-3 rounded-lg mb-3" style={{ backgroundColor: `${C.red}18`, border: `1px solid ${C.red}40` }}>
          <p className="text-sm font-semibold" style={{ color: C.red }}>⚠ Relevé hors limite — Non-conformité créée automatiquement</p>
          <p className="text-xs mt-1" style={{ color: C.text }}>Le relevé a été classé « Non conforme » et une non-conformité a été ouverte automatiquement. Retrouvez le lien vers la NC et créez une action CAPA directement depuis la ligne correspondante ci-dessous.</p>
        </div>
      )}
    </div>
  );
}

function HaccpSurveillanceTab({ studyId, ccpId, onStudyChange, onCcpChange }) {
  const C = useTheme();
  const usersQ = useCollection('/users');
  const studiesQ = useCollection('/haccp/studies');
  const ccpsQ = useCollection(studyId ? `/haccp/studies/${studyId}/ccps` : null);
  const recordsQ = useCollection(ccpId ? `/haccp/ccps/${ccpId}/monitoring` : null);
  const ccps = ccpsQ.data || [];
  const selectedCcp = ccps.find((c) => c.id === ccpId);
  return (
    <div className="space-y-4">
      <LiveBadge />
      <Panel title="Sélection du point de contrôle">
        <div className="grid grid-cols-2 gap-3">
          <FormField label="Étude HACCP">
            <select value={studyId || ''} onChange={(e) => { onStudyChange(e.target.value || null); onCcpChange(null); }} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)}>
              <option value="">Sélectionner une étude…</option>{(studiesQ.data || []).map((s) => <option key={s.id} value={s.id}>{s.code} — {s.name}</option>)}
            </select>
          </FormField>
          <FormField label="CCP / CP">
            <select value={ccpId || ''} onChange={(e) => onCcpChange(e.target.value || null)} disabled={!studyId} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)}>
              <option value="">Sélectionner un CCP/CP…</option>{ccps.map((c) => <option key={c.id} value={c.id}>{c.reference} — {c.dangerMaitrise || c.parametre || ''}</option>)}
            </select>
          </FormField>
        </div>
      </Panel>
      {ccpId && selectedCcp && (
        <>
          <Panel title={`Nouveau relevé — ${selectedCcp.reference}`} subtitle={selectedCcp.limiteCritique ? `Limite critique : ${selectedCcp.limiteCritique}` : undefined}>
            <HaccpMonitoringForm ccpId={ccpId} usersQ={usersQ} onCreated={recordsQ.reload} />
          </Panel>
          <Panel title="Historique des relevés" subtitle={`${(recordsQ.data || []).length} relevé(s)`}>
            {recordsQ.loading ? <LoadingPanel /> : recordsQ.error ? <ErrorPanel message={recordsQ.error} onRetry={recordsQ.reload} /> : (
              (recordsQ.data || []).length
                ? <div className="space-y-2">{recordsQ.data.map((r) => <HaccpMonitoringRow key={r.id} record={r} onChanged={recordsQ.reload} />)}</div>
                : <p className="text-sm text-center py-6" style={{ color: C.textMuted }}>Aucun relevé enregistré pour ce point de contrôle</p>
            )}
          </Panel>
        </>
      )}
    </div>
  );
}

function HaccpPrpFormModal({ record, studiesQ, usersQ, onClose, onCreated }) {
  const C = useTheme();
  const editing = !!record;
  const [form, setForm] = useState({ studyId: record?.studyId || '', type: record?.type || 'HYGIENE_PERSONNEL', libelle: record?.libelle || '', description: record?.description || '', frequence: record?.frequence || '', responsableId: record?.responsableId || '', active: record?.active ?? true });
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState(null);
  async function submit(e) {
    e.preventDefault();
    if (!form.libelle.trim()) { setError('Le libellé est obligatoire.'); return; }
    setSaving(true); setError(null);
    try {
      const payload = { ...form, studyId: form.studyId || null, responsableId: form.responsableId || null };
      if (editing) await api.patch(`/haccp/prps/${record.id}`, payload);
      else await api.post('/haccp/prps', payload);
      onCreated(); onClose();
    } catch (err) { setError(err.message); }
    setSaving(false);
  }
  async function del() {
    setSaving(true);
    try { await confirmAndDelete(record.libelle, `/haccp/prps/${record.id}`, () => { onCreated(); onClose(); }); }
    catch (err) { setError(err.message); }
    setSaving(false);
  }
  return (
    <Modal title={editing ? 'Modifier le PRP' : 'Nouveau PRP / BPH'} onClose={onClose}>
      <form onSubmit={submit}>
        <FormField label="Type">
          <select value={form.type} onChange={(e) => setForm({ ...form, type: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)}>
            {Object.entries(HACCP_PRP_TYPE_LABELS).map(([v, l]) => <option key={v} value={v}>{l}</option>)}
          </select>
        </FormField>
        <FormField label="Libellé *"><input value={form.libelle} onChange={(e) => setForm({ ...form, libelle: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
        <FormField label="Description"><textarea value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} rows={2} className="w-full px-3 py-2 rounded-lg text-sm outline-none resize-none" style={inputStyle(C)} /></FormField>
        <div className="grid grid-cols-2 gap-3">
          <FormField label="Fréquence"><input value={form.frequence} onChange={(e) => setForm({ ...form, frequence: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
          <FormField label="Étude HACCP (optionnel)">
            <select value={form.studyId} onChange={(e) => setForm({ ...form, studyId: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)}>
              <option value="">—</option>{(studiesQ.data || []).map((s) => <option key={s.id} value={s.id}>{s.code} — {s.name}</option>)}
            </select>
          </FormField>
        </div>
        <FormField label="Responsable">
          <select value={form.responsableId} onChange={(e) => setForm({ ...form, responsableId: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)}>
            <option value="">—</option>{(usersQ.data || []).map((u) => <option key={u.id} value={u.id}>{u.firstName} {u.lastName}</option>)}
          </select>
        </FormField>
        <label className="flex items-center gap-2 text-xs mb-3" style={{ color: C.textMuted }}>
          <input type="checkbox" checked={form.active} onChange={(e) => setForm({ ...form, active: e.target.checked })} /> Actif
        </label>
        {error && <p className="text-xs mb-3" style={{ color: C.red }}>{error}</p>}
        <div className="flex gap-2">
          {editing && <button type="button" onClick={del} disabled={saving} className="px-4 py-2.5 rounded-lg text-sm font-medium" style={{ backgroundColor: `${C.red}22`, color: C.red }}>Supprimer</button>}
          <button type="submit" disabled={saving} className="flex-1 py-2.5 rounded-lg text-sm font-medium" style={{ backgroundColor: C.blue, color: '#fff', opacity: saving ? 0.7 : 1 }}>{saving ? 'Enregistrement…' : editing ? 'Enregistrer les modifications' : 'Créer le PRP'}</button>
        </div>
      </form>
    </Modal>
  );
}

function HaccpPrpTab() {
  const C = useTheme();
  const prpsQ = useCollection('/haccp/prps');
  const studiesQ = useCollection('/haccp/studies');
  const usersQ = useCollection('/users');
  const [showForm, setShowForm] = useState(false);
  const [editingPrp, setEditingPrp] = useState(null);
  if (prpsQ.loading) return <LoadingPanel />;
  if (prpsQ.error) return <ErrorPanel message={prpsQ.error} onRetry={prpsQ.reload} />;
  const list = prpsQ.data || [];
  return (
    <div className="space-y-4">
      {(showForm || editingPrp) && <HaccpPrpFormModal record={editingPrp} studiesQ={studiesQ} usersQ={usersQ} onClose={() => { setShowForm(false); setEditingPrp(null); }} onCreated={prpsQ.reload} />}
      <div className="flex items-center justify-between">
        <LiveBadge />
        <button onClick={() => setShowForm(true)} className="px-3 py-1.5 rounded-lg text-xs font-medium" style={{ backgroundColor: C.green, color: '#052e1f' }}>+ Nouveau PRP</button>
      </div>
      <Panel title="Programmes prérequis / Bonnes pratiques d'hygiène" subtitle={`${list.length} PRP`}>
        {list.length
          ? <DataTable columns={['Type', 'Libellé', 'Fréquence', 'Statut']}
              rows={list.map((p) => [HACCP_PRP_TYPE_LABELS[p.type] || p.type, p.libelle, p.frequence || '—', <StatusChip statut={p.active ? 'Conforme' : 'Non conforme'} />])}
              onRowClick={(i) => setEditingPrp(list[i])} />
          : <p className="text-sm text-center py-6" style={{ color: C.textMuted }}>Aucun PRP enregistré pour le moment</p>}
      </Panel>
    </div>
  );
}

function HaccpMatriceTab() {
  const C = useTheme();
  const matriceQ = useCollection('/haccp/matrice');
  if (matriceQ.loading) return <LoadingPanel />;
  if (matriceQ.error) return <ErrorPanel message={matriceQ.error} onRetry={matriceQ.reload} />;
  const list = matriceQ.data || [];
  return (
    <div className="space-y-4">
      <LiveBadge />
      <Panel title="Matrice HACCP" subtitle={`${list.length} ligne(s)`}>
        {list.length
          ? <DataTable columns={['Étude', 'Étape', 'Danger', 'Type', 'Niveau de risque', 'CCP/CP', 'Statut']}
              rows={list.map((l) => [`${l.etudeCode} — ${l.etude}`, l.etape, l.danger, HACCP_HAZARD_TYPE_LABELS[l.type] || l.type, l.niveauRisque ? <span style={{ color: haccpRiskColor(C, l.niveauRisque) }}>{HACCP_RISK_LEVEL_LABELS[l.niveauRisque] || l.niveauRisque}</span> : '—', l.ccp ? `${l.ccp} (${l.ccpType})` : '—', l.statut || '—'])} />
          : <p className="text-sm text-center py-6" style={{ color: C.textMuted }}>Aucune donnée dans la matrice</p>}
      </Panel>
    </div>
  );
}

function HaccpOverviewTab({ onOpenMonitoring }) {
  const C = useTheme();
  const dashboardQ = useCollection('/haccp/dashboard');
  const todayQ = useCollection('/haccp/monitoring/today');
  const overdueQ = useCollection('/haccp/monitoring/overdue');
  if (dashboardQ.loading) return <LoadingPanel />;
  if (dashboardQ.error) return <ErrorPanel message={dashboardQ.error} onRetry={dashboardQ.reload} />;
  const d = dashboardQ.data || {};
  const today = todayQ.data || [];
  const overdue = overdueQ.data || [];
  function row(r) {
    return (
      <div key={r.id} onClick={() => onOpenMonitoring(r.ccp?.studyId, r.ccpId)} className="flex items-center justify-between p-2 rounded-lg cursor-pointer" style={{ backgroundColor: C.cardAlt }}>
        <div><span className="text-sm" style={{ color: C.text }}>{r.ccp?.reference} — {r.ccp?.dangerMaitrise || r.ccp?.parametre || ''}</span>{r.datePrevue && <span className="text-xs ml-2" style={{ color: C.textMuted }}>{new Date(r.datePrevue).toLocaleString('fr-FR')}</span>}</div>
        <StatusChip statut={HACCP_MONITORING_STATUS_LABELS[r.statut] || r.statut} />
      </div>
    );
  }
  return (
    <div className="space-y-6">
      <LiveBadge />
      <div className="flex flex-wrap gap-3">
        <KpiCard label="Études actives" value={d.etudesActives ?? '—'} objectif={`${d.etudesTotal ?? 0} au total`} color={C.blue} icon={ClipboardList} />
        <KpiCard label="Étapes" value={d.etapes ?? '—'} color={C.blue} icon={ClipboardList} />
        <KpiCard label="Dangers identifiés" value={d.dangers ?? '—'} color={C.amber} icon={AlertTriangle} />
        <KpiCard label="CCP actifs" value={d.ccp ?? '—'} color={C.red} icon={ShieldCheck} />
        <KpiCard label="CP actifs" value={d.cp ?? '—'} color={C.blue} icon={ShieldCheck} />
        <KpiCard label="CCP en anomalie" value={d.ccpEnAnomalie ?? '—'} color={d.ccpEnAnomalie > 0 ? C.red : C.green} icon={AlertTriangle} />
      </div>
      <div className="flex flex-wrap gap-3">
        <KpiCard label="Contrôles réalisés" value={d.controlesRealises ?? '—'} color={C.blue} icon={CheckCircle2} />
        <KpiCard label="Contrôles conformes" value={d.controlesConformes ?? '—'} color={C.green} icon={CheckCircle2} />
        <KpiCard label="Contrôles non conformes" value={d.controlesNonConformes ?? '—'} color={d.controlesNonConformes > 0 ? C.red : C.green} icon={AlertTriangle} />
        <KpiCard label="Contrôles en retard" value={d.controlesEnRetard ?? '—'} color={d.controlesEnRetard > 0 ? C.red : C.green} icon={AlertTriangle} />
        <KpiCard label="Taux de réalisation" value={d.tauxRealisation != null ? `${d.tauxRealisation}%` : '—'} color={C.blue} icon={Activity} />
        <KpiCard label="Taux de conformité" value={d.tauxConformite != null ? `${d.tauxConformite}%` : '—'} color={C.green} icon={Activity} />
      </div>
      <div className="flex flex-wrap gap-3">
        <KpiCard label="Non-conformités HACCP ouvertes" value={d.ncOuvertes ?? '—'} color={d.ncOuvertes > 0 ? C.red : C.green} icon={FileWarning} />
        <KpiCard label="Actions CAPA ouvertes" value={d.actionsOuvertes ?? '—'} color={C.blue} icon={Wrench} />
        <KpiCard label="Actions CAPA en retard" value={d.actionsEnRetard ?? '—'} color={d.actionsEnRetard > 0 ? C.red : C.green} icon={AlertTriangle} />
      </div>
      <Panel title="Contrôles du jour" subtitle={`${today.length} contrôle(s)`}>
        {todayQ.loading ? <LoadingPanel /> : today.length ? <div className="space-y-1.5">{today.map(row)}</div> : <p className="text-sm text-center py-6" style={{ color: C.textMuted }}>Aucun contrôle prévu aujourd'hui</p>}
      </Panel>
      <Panel title="Contrôles en retard" subtitle={`${overdue.length} contrôle(s)`}>
        {overdueQ.loading ? <LoadingPanel /> : overdue.length ? <div className="space-y-1.5">{overdue.map(row)}</div> : <p className="text-sm text-center py-6" style={{ color: C.textMuted }}>Aucun contrôle en retard</p>}
      </Panel>
    </div>
  );
}

function HaccpPage() {
  const C = useTheme();
  const [tab, setTab] = useState('apercu');
  const [surveillanceStudyId, setSurveillanceStudyId] = useState(null);
  const [surveillanceCcpId, setSurveillanceCcpId] = useState(null);
  function openMonitoring(studyId, ccpId) {
    setSurveillanceStudyId(studyId || null); setSurveillanceCcpId(ccpId || null); setTab('surveillance');
  }
  return (
    <div className="space-y-6">
      <div className="flex flex-wrap gap-2">
        {[['apercu', "Vue d'ensemble"], ['etudes', 'Études'], ['surveillance', 'Surveillance'], ['prp', 'PRP / BPH'], ['matrice', 'Matrice']].map(([id, label]) => (
          <button key={id} onClick={() => setTab(id)} className="px-3 py-1.5 rounded-lg text-xs font-medium" style={{ backgroundColor: tab === id ? C.blue : 'transparent', color: tab === id ? '#fff' : C.textMuted }}>{label}</button>
        ))}
      </div>
      {tab === 'apercu' && <HaccpOverviewTab onOpenMonitoring={openMonitoring} />}
      {tab === 'etudes' && <HaccpEtudesTab />}
      {tab === 'surveillance' && <HaccpSurveillanceTab studyId={surveillanceStudyId} ccpId={surveillanceCcpId} onStudyChange={setSurveillanceStudyId} onCcpChange={setSurveillanceCcpId} />}
      {tab === 'prp' && <HaccpPrpTab />}
      {tab === 'matrice' && <HaccpMatriceTab />}
    </div>
  );
}

function EquipmentMaintenanceTab({ equipment, onChanged }) {
  const C = useTheme();
  const plansQ = useCollection(`/business/equipment-maintenance-plans?equipmentId=${equipment.id}`);
  const recordsQ = useCollection(`/business/equipment-maintenance-records?equipmentId=${equipment.id}`);
  const statsQ = useCollection(`/business/equipment/${equipment.id}/maintenance-stats`);
  const usersQ = useCollection('/users');
  const [showPlanForm, setShowPlanForm] = useState(false);
  const [showRecordForm, setShowRecordForm] = useState(false);
  const [planForm, setPlanForm] = useState({ designation: '', frequenceType: 'CALENDAIRE', frequenceValeur: 30, responsableId: '' });
  const [recordForm, setRecordForm] = useState({ type: 'CORRECTIVE', statut: 'TERMINEE', planId: '', datePanne: '', dateDebut: '', dateFin: '', dureeHeures: '', cout: '', description: '', causePanne: '', piecesRemplacees: '' });
  const [saving, setSaving] = useState(false);
  function reload() { plansQ.reload(); recordsQ.reload(); statsQ.reload(); onChanged(); }
  async function submitPlan(e) {
    e.preventDefault(); setSaving(true);
    try { await api.post('/business/equipment-maintenance-plans', { ...planForm, equipmentId: equipment.id, frequenceValeur: Number(planForm.frequenceValeur), responsableId: planForm.responsableId || null }); setShowPlanForm(false); reload(); }
    catch (err) { alert(err.message); }
    setSaving(false);
  }
  async function submitRecord(e) {
    e.preventDefault(); setSaving(true);
    try {
      await api.post('/business/equipment-maintenance-records', {
        ...recordForm, equipmentId: equipment.id, planId: recordForm.planId || null,
        datePanne: recordForm.datePanne ? new Date(recordForm.datePanne).toISOString() : null,
        dateDebut: recordForm.dateDebut ? new Date(recordForm.dateDebut).toISOString() : null,
        dateFin: recordForm.dateFin ? new Date(recordForm.dateFin).toISOString() : null,
        dureeHeures: recordForm.dureeHeures === '' ? null : Number(recordForm.dureeHeures),
        cout: recordForm.cout === '' ? null : Number(recordForm.cout),
      });
      setShowRecordForm(false); reload();
    } catch (err) { alert(err.message); }
    setSaving(false);
  }
  const stats = statsQ.data;
  return (
    <div className="space-y-4">
      {stats && (
        <div className="flex flex-wrap gap-3">
          <KpiCard label="Pannes enregistrées" value={stats.nombrePannes} color={C.blue} icon={Wrench} />
          <KpiCard label="MTBF (h)" value={stats.mtbfHeures != null ? Math.round(stats.mtbfHeures) : '—'} color={C.blue} icon={Activity} />
          <KpiCard label="MTTR (h)" value={stats.mttrHeures != null ? Math.round(stats.mttrHeures) : '—'} color={C.amber} icon={Activity} />
          <KpiCard label="Disponibilité" value={stats.disponibilite != null ? `${Math.round(stats.disponibilite * 100)}%` : '—'} color={C.green} icon={CheckCircle2} />
        </div>
      )}
      <Panel title="Plans de maintenance préventive" right={<button onClick={() => setShowPlanForm(!showPlanForm)} className="text-xs px-2 py-1.5 rounded-lg font-medium" style={{ backgroundColor: C.green, color: '#052e1f' }}>+ Nouveau plan</button>}>
        {showPlanForm && (
          <form onSubmit={submitPlan} className="mb-4 p-3 rounded-lg space-y-2" style={{ backgroundColor: C.cardAlt, border: `1px solid ${C.border}` }}>
            <div className="grid grid-cols-2 gap-3">
              <FormField label="Désignation"><input required value={planForm.designation} onChange={(e) => setPlanForm({ ...planForm, designation: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
              <FormField label="Responsable (optionnel)">
                <select value={planForm.responsableId} onChange={(e) => setPlanForm({ ...planForm, responsableId: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)}>
                  <option value="">—</option>{(usersQ.data || []).map((u) => <option key={u.id} value={u.id}>{u.firstName} {u.lastName}</option>)}
                </select>
              </FormField>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <FormField label="Type de fréquence">
                <select value={planForm.frequenceType} onChange={(e) => setPlanForm({ ...planForm, frequenceType: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)}>
                  <option value="CALENDAIRE">Calendaire (jours)</option><option value="HEURES">Heures de fonctionnement</option><option value="KM">Kilométrage</option><option value="CYCLES">Cycles</option><option value="RECOMMANDATION_FABRICANT">Recommandation fabricant</option><option value="RISQUE">Basée sur le risque</option>
                </select>
              </FormField>
              <FormField label="Valeur"><input type="number" required value={planForm.frequenceValeur} onChange={(e) => setPlanForm({ ...planForm, frequenceValeur: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
            </div>
            <button type="submit" disabled={saving} className="px-4 py-2 rounded-lg text-sm font-medium" style={{ backgroundColor: C.blue, color: '#fff' }}>Enregistrer</button>
          </form>
        )}
        {plansQ.data?.length
          ? <DataTable columns={['Désignation', 'Fréquence', 'Dernière', 'Prochaine', 'Responsable']}
              rows={plansQ.data.map((p) => [p.designation, `${p.frequenceValeur} (${p.frequenceType})`, p.dateDerniere ? new Date(p.dateDerniere).toLocaleDateString('fr-FR') : '—', p.dateProchaine ? new Date(p.dateProchaine).toLocaleDateString('fr-FR') : '—', p.responsable ? `${p.responsable.firstName} ${p.responsable.lastName}` : '—'])} />
          : <p className="text-sm text-center py-4" style={{ color: C.textMuted }}>Aucun plan de maintenance préventive</p>}
      </Panel>
      <Panel title="Interventions (préventives et correctives)" right={<button onClick={() => setShowRecordForm(!showRecordForm)} className="text-xs px-2 py-1.5 rounded-lg font-medium" style={{ backgroundColor: C.green, color: '#052e1f' }}>+ Nouvelle intervention</button>}>
        {showRecordForm && (
          <form onSubmit={submitRecord} className="mb-4 p-3 rounded-lg space-y-2" style={{ backgroundColor: C.cardAlt, border: `1px solid ${C.border}` }}>
            <div className="grid grid-cols-3 gap-3">
              <FormField label="Type">
                <select value={recordForm.type} onChange={(e) => setRecordForm({ ...recordForm, type: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)}>
                  <option value="CORRECTIVE">Corrective (panne)</option><option value="PREVENTIVE">Préventive</option>
                </select>
              </FormField>
              <FormField label="Statut">
                <select value={recordForm.statut} onChange={(e) => setRecordForm({ ...recordForm, statut: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)}>
                  <option value="PLANIFIEE">Planifiée</option><option value="EN_COURS">En cours</option><option value="TERMINEE">Terminée</option><option value="REPORTEE">Reportée</option>
                </select>
              </FormField>
              {recordForm.type === 'PREVENTIVE' && (
                <FormField label="Plan lié (optionnel)">
                  <select value={recordForm.planId} onChange={(e) => setRecordForm({ ...recordForm, planId: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)}>
                    <option value="">—</option>{(plansQ.data || []).map((p) => <option key={p.id} value={p.id}>{p.designation}</option>)}
                  </select>
                </FormField>
              )}
            </div>
            <div className="grid grid-cols-3 gap-3">
              {recordForm.type === 'CORRECTIVE' && <FormField label="Date de panne"><input type="date" value={recordForm.datePanne} onChange={(e) => setRecordForm({ ...recordForm, datePanne: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>}
              <FormField label="Début d'intervention"><input type="date" value={recordForm.dateDebut} onChange={(e) => setRecordForm({ ...recordForm, dateDebut: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
              <FormField label="Fin d'intervention"><input type="date" value={recordForm.dateFin} onChange={(e) => setRecordForm({ ...recordForm, dateFin: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <FormField label="Durée (heures, optionnel)"><input type="number" value={recordForm.dureeHeures} onChange={(e) => setRecordForm({ ...recordForm, dureeHeures: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
              <FormField label="Coût (optionnel)"><input type="number" value={recordForm.cout} onChange={(e) => setRecordForm({ ...recordForm, cout: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
            </div>
            {recordForm.type === 'CORRECTIVE' && <FormField label="Cause de la panne (optionnel)"><input value={recordForm.causePanne} onChange={(e) => setRecordForm({ ...recordForm, causePanne: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>}
            <FormField label="Description (optionnel)"><textarea value={recordForm.description} onChange={(e) => setRecordForm({ ...recordForm, description: e.target.value })} rows={2} className="w-full px-3 py-2 rounded-lg text-sm outline-none resize-none" style={inputStyle(C)} /></FormField>
            <button type="submit" disabled={saving} className="px-4 py-2 rounded-lg text-sm font-medium" style={{ backgroundColor: C.blue, color: '#fff' }}>Enregistrer</button>
          </form>
        )}
        {recordsQ.data?.length
          ? <DataTable columns={['Type', 'Statut', 'Date', 'Durée (h)', 'Coût']}
              rows={recordsQ.data.map((r) => [r.type === 'PREVENTIVE' ? 'Préventive' : 'Corrective', r.statut, (r.datePanne || r.dateDebut) ? new Date(r.datePanne || r.dateDebut).toLocaleDateString('fr-FR') : '—', r.dureeHeures ?? '—', r.cout ? `${r.cout} FCFA` : '—'])} />
          : <p className="text-sm text-center py-4" style={{ color: C.textMuted }}>Aucune intervention enregistrée</p>}
      </Panel>
    </div>
  );
}

function EquipmentControlsTab({ equipment, onChanged }) {
  const C = useTheme();
  const controlsQ = useCollection(`/business/equipment-controls?equipmentId=${equipment.id}`);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({ designation: '', organisme: '', referenceReglementaire: '', dateControle: new Date().toISOString().slice(0, 10), dateProchainControle: '', statut: 'CONFORME', observations: '' });
  const [saving, setSaving] = useState(false);
  const [genId, setGenId] = useState(null);
  function reload() { controlsQ.reload(); onChanged(); }
  async function submit(e) {
    e.preventDefault(); setSaving(true);
    try {
      await api.post('/business/equipment-controls', { ...form, equipmentId: equipment.id, dateControle: new Date(form.dateControle).toISOString(), dateProchainControle: form.dateProchainControle ? new Date(form.dateProchainControle).toISOString() : null });
      setShowForm(false); reload();
    } catch (err) { alert(err.message); }
    setSaving(false);
  }
  async function generateNc(id) {
    setGenId(id);
    try { await api.post(`/business/equipment-controls/${id}/generate-nc`, {}); reload(); }
    catch (err) { alert(err.message); }
    setGenId(null);
  }
  return (
    <Panel title="Contrôles réglementaires" right={<button onClick={() => setShowForm(!showForm)} className="text-xs px-2 py-1.5 rounded-lg font-medium" style={{ backgroundColor: C.green, color: '#052e1f' }}>+ Nouveau contrôle</button>}>
      {showForm && (
        <form onSubmit={submit} className="mb-4 p-3 rounded-lg space-y-2" style={{ backgroundColor: C.cardAlt, border: `1px solid ${C.border}` }}>
          <div className="grid grid-cols-2 gap-3">
            <FormField label="Désignation"><input required value={form.designation} onChange={(e) => setForm({ ...form, designation: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
            <FormField label="Organisme (optionnel)"><input value={form.organisme} onChange={(e) => setForm({ ...form, organisme: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
          </div>
          <div className="grid grid-cols-3 gap-3">
            <FormField label="Date du contrôle"><input type="date" required value={form.dateControle} onChange={(e) => setForm({ ...form, dateControle: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
            <FormField label="Prochain contrôle (optionnel)"><input type="date" value={form.dateProchainControle} onChange={(e) => setForm({ ...form, dateProchainControle: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
            <FormField label="Statut">
              <select value={form.statut} onChange={(e) => setForm({ ...form, statut: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)}>
                <option value="CONFORME">Conforme</option><option value="CONFORME_AVEC_OBSERVATIONS">Conforme avec observations</option><option value="NON_CONFORME">Non conforme</option><option value="EN_ATTENTE">En attente</option><option value="EXPIRE">Expiré</option>
              </select>
            </FormField>
          </div>
          <FormField label="Observations (optionnel)"><textarea value={form.observations} onChange={(e) => setForm({ ...form, observations: e.target.value })} rows={2} className="w-full px-3 py-2 rounded-lg text-sm outline-none resize-none" style={inputStyle(C)} /></FormField>
          <button type="submit" disabled={saving} className="px-4 py-2 rounded-lg text-sm font-medium" style={{ backgroundColor: C.blue, color: '#fff' }}>Enregistrer</button>
        </form>
      )}
      {controlsQ.data?.length
        ? <DataTable columns={['Désignation', 'Organisme', 'Date', 'Prochain', 'Statut', 'Action']}
            rows={controlsQ.data.map((c) => [c.designation, c.organisme || '—', new Date(c.dateControle).toLocaleDateString('fr-FR'), c.dateProchainControle ? new Date(c.dateProchainControle).toLocaleDateString('fr-FR') : '—', <StatusChip statut={c.statut} />,
              (c.statut === 'NON_CONFORME' && !c.nonConformityId) ? <button onClick={() => generateNc(c.id)} disabled={genId === c.id} className="text-[11px] px-2 py-0.5 rounded-full" style={{ backgroundColor: `${C.amber}22`, color: C.amber }}>{genId === c.id ? '…' : 'Générer une NC'}</button> : (c.nonConformityId ? 'NC créée' : '—')])} />
        : <p className="text-sm text-center py-4" style={{ color: C.textMuted }}>Aucun contrôle réglementaire enregistré</p>}
    </Panel>
  );
}

function EquipmentCalibrationsTab({ equipment, onChanged }) {
  const C = useTheme();
  const calibQ = useCollection(`/business/equipment-calibrations?equipmentId=${equipment.id}`);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({ dateEtalonnage: new Date().toISOString().slice(0, 10), dateProchaineEtalonnage: '', organismeEtalonneur: '', certificatNumero: '', resultat: 'CONFORME', incertitude: '' });
  const [saving, setSaving] = useState(false);
  const [genId, setGenId] = useState(null);
  function reload() { calibQ.reload(); onChanged(); }
  async function submit(e) {
    e.preventDefault(); setSaving(true);
    try {
      await api.post('/business/equipment-calibrations', { ...form, equipmentId: equipment.id, dateEtalonnage: new Date(form.dateEtalonnage).toISOString(), dateProchaineEtalonnage: form.dateProchaineEtalonnage ? new Date(form.dateProchaineEtalonnage).toISOString() : null });
      setShowForm(false); reload();
    } catch (err) { alert(err.message); }
    setSaving(false);
  }
  async function generateNc(id) {
    setGenId(id);
    try { await api.post(`/business/equipment-calibrations/${id}/generate-nc`, {}); reload(); }
    catch (err) { alert(err.message); }
    setGenId(null);
  }
  return (
    <Panel title="Étalonnage des instruments de mesure" right={<button onClick={() => setShowForm(!showForm)} className="text-xs px-2 py-1.5 rounded-lg font-medium" style={{ backgroundColor: C.green, color: '#052e1f' }}>+ Nouvel étalonnage</button>}>
      {showForm && (
        <form onSubmit={submit} className="mb-4 p-3 rounded-lg space-y-2" style={{ backgroundColor: C.cardAlt, border: `1px solid ${C.border}` }}>
          <div className="grid grid-cols-3 gap-3">
            <FormField label="Date d'étalonnage"><input type="date" required value={form.dateEtalonnage} onChange={(e) => setForm({ ...form, dateEtalonnage: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
            <FormField label="Prochain étalonnage (optionnel)"><input type="date" value={form.dateProchaineEtalonnage} onChange={(e) => setForm({ ...form, dateProchaineEtalonnage: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
            <FormField label="Résultat">
              <select value={form.resultat} onChange={(e) => setForm({ ...form, resultat: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)}>
                <option value="CONFORME">Conforme</option><option value="CONFORME_AVEC_AJUSTEMENT">Conforme avec ajustement</option><option value="NON_CONFORME">Non conforme</option>
              </select>
            </FormField>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <FormField label="Organisme étalonneur (optionnel)"><input value={form.organismeEtalonneur} onChange={(e) => setForm({ ...form, organismeEtalonneur: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
            <FormField label="N° certificat (optionnel)"><input value={form.certificatNumero} onChange={(e) => setForm({ ...form, certificatNumero: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
          </div>
          <button type="submit" disabled={saving} className="px-4 py-2 rounded-lg text-sm font-medium" style={{ backgroundColor: C.blue, color: '#fff' }}>Enregistrer</button>
        </form>
      )}
      {calibQ.data?.length
        ? <DataTable columns={['Date', 'Prochain', 'Résultat', 'Ne pas utiliser', 'Action']}
            rows={calibQ.data.map((c) => [new Date(c.dateEtalonnage).toLocaleDateString('fr-FR'), c.dateProchaineEtalonnage ? new Date(c.dateProchaineEtalonnage).toLocaleDateString('fr-FR') : '—', <StatusChip statut={c.resultat} />, c.nePasUtiliser ? <span style={{ color: C.red, fontWeight: 600 }}>Oui</span> : 'Non',
              (c.resultat !== 'CONFORME' && !c.nonConformityId) ? <button onClick={() => generateNc(c.id)} disabled={genId === c.id} className="text-[11px] px-2 py-0.5 rounded-full" style={{ backgroundColor: `${C.amber}22`, color: C.amber }}>{genId === c.id ? '…' : 'Générer une NC'}</button> : (c.nonConformityId ? 'NC créée' : '—')])} />
        : <p className="text-sm text-center py-4" style={{ color: C.textMuted }}>Aucun étalonnage enregistré</p>}
    </Panel>
  );
}

function EquipmentConsignationsTab({ equipment, onChanged }) {
  const C = useTheme();
  const consQ = useCollection(`/business/equipment-consignations?equipmentId=${equipment.id}`);
  const usersQ = useCollection('/users');
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({ motif: '', dateFinPrevue: '', risqueAssocie: '', mesureControle: '', responsableId: '' });
  const [saving, setSaving] = useState(false);
  const [busyId, setBusyId] = useState(null);
  function reload() { consQ.reload(); onChanged(); }
  async function submit(e) {
    e.preventDefault(); setSaving(true);
    try {
      await api.post('/business/equipment-consignations', { ...form, equipmentId: equipment.id, responsableId: form.responsableId || null, dateFinPrevue: form.dateFinPrevue ? new Date(form.dateFinPrevue).toISOString() : null });
      setShowForm(false); reload();
    } catch (err) { alert(err.message); }
    setSaving(false);
  }
  async function lever(id) {
    setBusyId(id);
    try { await api.post(`/business/equipment-consignations/${id}/lever`, {}); reload(); }
    catch (err) { alert(err.message); }
    setBusyId(null);
  }
  return (
    <Panel title="Consignation / cadenassage (LOTO)" subtitle="Tant qu'une consignation est en cours, l'équipement passe à l'état Consigné" right={<button onClick={() => setShowForm(!showForm)} className="text-xs px-2 py-1.5 rounded-lg font-medium" style={{ backgroundColor: C.green, color: '#052e1f' }}>+ Nouvelle consignation</button>}>
      {showForm && (
        <form onSubmit={submit} className="mb-4 p-3 rounded-lg space-y-2" style={{ backgroundColor: C.cardAlt, border: `1px solid ${C.border}` }}>
          <FormField label="Motif"><input required value={form.motif} onChange={(e) => setForm({ ...form, motif: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
          <div className="grid grid-cols-2 gap-3">
            <FormField label="Fin prévue (optionnel)"><input type="date" value={form.dateFinPrevue} onChange={(e) => setForm({ ...form, dateFinPrevue: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
            <FormField label="Responsable (optionnel)">
              <select value={form.responsableId} onChange={(e) => setForm({ ...form, responsableId: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)}>
                <option value="">—</option>{(usersQ.data || []).map((u) => <option key={u.id} value={u.id}>{u.firstName} {u.lastName}</option>)}
              </select>
            </FormField>
          </div>
          <FormField label="Risque associé (optionnel)"><input value={form.risqueAssocie} onChange={(e) => setForm({ ...form, risqueAssocie: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
          <FormField label="Mesure de maîtrise (optionnel)"><input value={form.mesureControle} onChange={(e) => setForm({ ...form, mesureControle: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
          <button type="submit" disabled={saving} className="px-4 py-2 rounded-lg text-sm font-medium" style={{ backgroundColor: C.blue, color: '#fff' }}>Enregistrer</button>
        </form>
      )}
      {consQ.data?.length
        ? <DataTable columns={['Motif', 'Début', 'Fin prévue', 'Statut', 'Action']}
            rows={consQ.data.map((c) => [c.motif, new Date(c.dateDebut).toLocaleDateString('fr-FR'), c.dateFinPrevue ? new Date(c.dateFinPrevue).toLocaleDateString('fr-FR') : '—', <StatusChip statut={c.statut} />,
              c.statut === 'EN_COURS' ? <button onClick={() => lever(c.id)} disabled={busyId === c.id} className="text-[11px] px-2 py-0.5 rounded-full font-medium" style={{ backgroundColor: `${C.green}22`, color: C.green }}>{busyId === c.id ? '…' : 'Lever la consignation'}</button> : '—'])} />
        : <p className="text-sm text-center py-4" style={{ color: C.textMuted }}>Aucune consignation enregistrée</p>}
    </Panel>
  );
}

function EquipmentLinksTab({ equipment, onChanged }) {
  const C = useTheme();
  const [busy, setBusy] = useState(false);
  async function run(action) {
    setBusy(true);
    try { await api.post(`/business/equipment/${equipment.id}/${action}`, {}); onChanged(); }
    catch (err) { alert(err.message); }
    setBusy(false);
  }
  const risks = equipment.risks || [], ncs = equipment.nonConformities || [], actions = equipment.actions || [], events = equipment.safetyEvents || [];
  return (
    <div className="space-y-4">
      <div className="flex flex-wrap gap-2">
        <button onClick={() => run('generate-risk')} disabled={busy} className="text-xs px-3 py-1.5 rounded-lg font-medium" style={{ backgroundColor: `${C.amber}22`, color: C.amber }}>Créer un risque associé</button>
        <button onClick={() => run('generate-nc')} disabled={busy} className="text-xs px-3 py-1.5 rounded-lg font-medium" style={{ backgroundColor: `${C.red}22`, color: C.red }}>Créer une non-conformité</button>
        <button onClick={() => run('generate-action')} disabled={busy} className="text-xs px-3 py-1.5 rounded-lg font-medium" style={{ backgroundColor: `${C.blue}22`, color: C.blue }}>Créer une action CAPA</button>
      </div>
      <Panel title={`Risques liés (${risks.length})`}>
        {risks.length ? <DataTable columns={['Code', 'Danger', 'Niveau', 'Statut']} rows={risks.map((r) => [r.code, r.hazard, r.grossLevel || '—', r.status])} /> : <p className="text-sm text-center py-4" style={{ color: C.textMuted }}>Aucun risque lié</p>}
      </Panel>
      <Panel title={`Non-conformités liées (${ncs.length})`}>
        {ncs.length ? <DataTable columns={['Code', 'Titre', 'Statut']} rows={ncs.map((n) => [n.code, n.title, n.status])} /> : <p className="text-sm text-center py-4" style={{ color: C.textMuted }}>Aucune non-conformité liée</p>}
      </Panel>
      <Panel title={`Actions CAPA liées (${actions.length})`}>
        {actions.length ? <DataTable columns={['Code', 'Titre', 'Statut', 'Échéance']} rows={actions.map((a) => [a.code, a.title, a.status, a.dueDate ? new Date(a.dueDate).toLocaleDateString('fr-FR') : '—'])} /> : <p className="text-sm text-center py-4" style={{ color: C.textMuted }}>Aucune action CAPA liée</p>}
      </Panel>
      <Panel title={`Accidents / incidents liés (${events.length})`}>
        {events.length ? <DataTable columns={['Date', 'Titre', 'Gravité']} rows={events.map((e) => [new Date(e.occurredAt).toLocaleDateString('fr-FR'), e.title, e.severity])} /> : <p className="text-sm text-center py-4" style={{ color: C.textMuted }}>Aucun accident/incident lié</p>}
      </Panel>
    </div>
  );
}

function EquipmentHistoryTab({ equipment }) {
  const C = useTheme();
  const logsQ = useCollection('/audit-logs?module=EQUIPMENT');
  if (logsQ.loading) return <LoadingPanel />;
  const list = (logsQ.data || []).filter((l) => l.entityId === equipment.id);
  return (
    <Panel title="Historique de l'équipement" subtitle="Toutes les créations et modifications, tracées automatiquement">
      {list.length
        ? <DataTable columns={['Date', 'Utilisateur', 'Action']}
            rows={list.map((l) => [new Date(l.createdAt).toLocaleString('fr-FR'), l.user ? `${l.user.firstName} ${l.user.lastName}` : 'Système', l.action === 'CREATE' ? 'Création' : l.action === 'UPDATE' ? 'Modification' : 'Suppression'])} />
        : <p className="text-sm text-center py-6" style={{ color: C.textMuted }}>Aucune action enregistrée pour le moment</p>}
    </Panel>
  );
}

function EquipmentQrTab({ equipment, onChanged }) {
  const C = useTheme();
  const [dataUrl, setDataUrl] = useState(null);
  const [busy, setBusy] = useState(false);
  const scanUrl = `${getBaseUrl()}/business/equipment/qr/${equipment.qrToken || ''}`;
  useEffect(() => {
    let cancelled = false;
    if (equipment.qrToken) {
      QRCode.toDataURL(scanUrl, { width: 260, margin: 1 }).then((url) => { if (!cancelled) setDataUrl(url); });
    } else {
      setDataUrl(null);
    }
    return () => { cancelled = true; };
  }, [equipment.qrToken]);
  async function regenerate() {
    setBusy(true);
    try { await api.post(`/business/equipment/${equipment.id}/regenerate-qr`, {}); onChanged(); } catch (err) { alert(err.message); }
    setBusy(false);
  }
  function download() {
    if (!dataUrl) return;
    const a = document.createElement('a');
    a.href = dataUrl; a.download = `QR_${equipment.code}.png`; a.click();
  }
  return (
    <div className="flex flex-col items-center gap-4 py-4">
      {dataUrl
        ? <img src={dataUrl} alt="QR code équipement" className="rounded-lg" style={{ border: `1px solid ${C.border}` }} />
        : <p className="text-sm" style={{ color: C.textMuted }}>Aucun code QR généré pour cet équipement.</p>}
      <p className="text-xs text-center max-w-xs" style={{ color: C.textMuted }}>
        Scanner ce code ouvre la fiche de l'équipement {equipment.code} (identification, maintenance, contrôles, historique récent).
      </p>
      <div className="flex gap-2 flex-wrap justify-center">
        <button onClick={download} disabled={!dataUrl} className="flex items-center gap-1.5 text-xs px-3 py-1.5 rounded-lg font-medium" style={{ backgroundColor: C.blue, color: '#fff', opacity: dataUrl ? 1 : 0.5 }}><Download size={14} /> Télécharger PNG</button>
        <button onClick={() => window.print()} disabled={!dataUrl} className="flex items-center gap-1.5 text-xs px-3 py-1.5 rounded-lg font-medium" style={{ backgroundColor: C.green, color: '#052e1f', opacity: dataUrl ? 1 : 0.5 }}><Printer size={14} /> Imprimer</button>
        <button onClick={regenerate} disabled={busy} className="text-xs px-3 py-1.5 rounded-lg font-medium" style={{ backgroundColor: C.cardAlt, border: `1px solid ${C.border}`, color: C.text }}>{busy ? '…' : 'Régénérer le code'}</button>
      </div>
    </div>
  );
}

function EquipmentDetailModal({ equipmentId, onClose, onChanged }) {
  const C = useTheme();
  const detailQ = useCollection(`/business/equipment/${equipmentId}`);
  const [tab, setTab] = useState('identification');
  const [editing, setEditing] = useState(false);
  if (detailQ.loading) return <Modal title="Équipement" onClose={onClose} wide><LoadingPanel /></Modal>;
  if (detailQ.error || !detailQ.data) return <Modal title="Équipement" onClose={onClose} wide><ErrorPanel message={detailQ.error} onRetry={detailQ.reload} /></Modal>;
  const eq = detailQ.data;
  function reload() { detailQ.reload(); onChanged(); }
  if (editing) return <EquipmentForm record={eq} onClose={() => setEditing(false)} onCreated={() => { setEditing(false); reload(); }} />;
  return (
    <Modal title={`${eq.code} — ${eq.name}`} onClose={onClose} wide>
      <div className="flex items-center justify-between mb-3 flex-wrap gap-2">
        <p className="text-xs" style={{ color: C.textMuted }}>{eq.categoryEq?.label || 'Sans catégorie'} · {eq.site?.name || 'Site non renseigné'}</p>
        <div className="flex gap-2">
          <span className="text-xs font-medium px-2 py-1 rounded-full" style={{ backgroundColor: `${equipmentEtatColor(C, eq.etat)}22`, color: equipmentEtatColor(C, eq.etat) }}>{EQUIPMENT_ETAT_LABELS[eq.etat] || eq.etat}</span>
          {eq.criticiteNiveau && <span className="text-xs font-medium px-2 py-1 rounded-full" style={{ backgroundColor: `${equipmentCriticiteColor(C, eq.criticiteNiveau)}22`, color: equipmentCriticiteColor(C, eq.criticiteNiveau) }}>Criticité {EQUIPMENT_CRITICITE_LABELS[eq.criticiteNiveau]}</span>}
        </div>
      </div>
      <div className="flex gap-2 flex-wrap mb-4">
        <button onClick={() => setEditing(true)} className="text-xs px-2 py-1.5 rounded-lg" style={{ backgroundColor: C.cardAlt, border: `1px solid ${C.border}`, color: C.text }}>Modifier</button>
        <button onClick={() => window.print()} className="flex items-center gap-1.5 text-xs px-2 py-1.5 rounded-lg" style={{ backgroundColor: C.cardAlt, border: `1px solid ${C.border}`, color: C.text }}><Printer size={14} /> Imprimer / PDF</button>
      </div>
      <div className="flex flex-wrap gap-2 mb-4">
        {[['identification', 'Identification'], ['maintenance', 'Maintenance'], ['controles', 'Contrôles'], ['etalonnage', 'Étalonnage'], ['consignation', 'Consignation'], ['liens', 'Risques / NC / CAPA'], ['qr', 'QR code'], ['historique', 'Historique']].map(([id, label]) => (
          <button key={id} onClick={() => setTab(id)} className="px-3 py-1.5 rounded-lg text-xs font-medium" style={{ backgroundColor: tab === id ? C.blue : 'transparent', color: tab === id ? '#fff' : C.textMuted }}>{label}</button>
        ))}
      </div>
      {tab === 'identification' && (
        <div className="grid grid-cols-2 gap-4 text-sm">
          {eq.type && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Type</p><p style={{ color: C.text }}>{eq.type}{eq.sousType ? ` / ${eq.sousType}` : ''}</p></div>}
          {(eq.marque || eq.modele) && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Marque / Modèle</p><p style={{ color: C.text }}>{eq.marque || '—'} {eq.modele || ''}</p></div>}
          {eq.numeroSerie && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>N° de série</p><p style={{ color: C.text }}>{eq.numeroSerie}</p></div>}
          {eq.anneeFabrication && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Année de fabrication</p><p style={{ color: C.text }}>{eq.anneeFabrication}</p></div>}
          {eq.fournisseur && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Fournisseur</p><p style={{ color: C.text }}>{eq.fournisseur.nom}</p></div>}
          {eq.workUnit && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Service / unité</p><p style={{ color: C.text }}>{eq.workUnit.name}</p></div>}
          {(eq.batiment || eq.zone) && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Bâtiment / Zone</p><p style={{ color: C.text }}>{eq.batiment || '—'} {eq.zone || ''}</p></div>}
          {eq.responsable && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Responsable</p><p style={{ color: C.text }}>{eq.responsable.firstName} {eq.responsable.lastName}</p></div>}
          {eq.utilisateursAutorises && <div className="col-span-2"><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Utilisateurs autorisés</p><p style={{ color: C.text }}>{eq.utilisateursAutorises}</p></div>}
          {(eq.criticiteSecurite != null || eq.criticiteQualite != null || eq.criticiteEnvironnement != null || eq.criticiteProduction != null) && (
            <div className="col-span-2">
              <p className="text-xs font-semibold mb-1" style={{ color: C.textMuted }}>Criticité par axe</p>
              <div className="flex gap-4 text-xs" style={{ color: C.text }}>
                <span>Sécurité : {eq.criticiteSecurite ?? '—'}</span><span>Qualité : {eq.criticiteQualite ?? '—'}</span><span>Environnement : {eq.criticiteEnvironnement ?? '—'}</span><span>Production : {eq.criticiteProduction ?? '—'}</span>
              </div>
            </div>
          )}
          {eq.notes && <div className="col-span-2"><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Notes</p><p style={{ color: C.text }}>{eq.notes}</p></div>}
        </div>
      )}
      {tab === 'maintenance' && <EquipmentMaintenanceTab equipment={eq} onChanged={reload} />}
      {tab === 'controles' && <EquipmentControlsTab equipment={eq} onChanged={reload} />}
      {tab === 'etalonnage' && <EquipmentCalibrationsTab equipment={eq} onChanged={reload} />}
      {tab === 'consignation' && <EquipmentConsignationsTab equipment={eq} onChanged={reload} />}
      {tab === 'liens' && <EquipmentLinksTab equipment={eq} onChanged={reload} />}
      {tab === 'qr' && <EquipmentQrTab equipment={eq} onChanged={reload} />}
      {tab === 'historique' && <EquipmentHistoryTab equipment={eq} />}
    </Modal>
  );
}

function equipmentExportRows(list) {
  const header = ['Code', 'Nom', 'Catégorie', 'Site', 'Service/Unité', 'Responsable', 'État', 'Criticité', 'Score criticité', 'N° de série', 'Marque', 'Modèle', 'Prochaine échéance'];
  const rows = list.map((e) => [
    e.code, e.name, e.categoryEq?.label || e.category || '', e.site?.name || '', e.workUnit?.name || '',
    e.responsable ? `${e.responsable.firstName} ${e.responsable.lastName}` : '', EQUIPMENT_ETAT_LABELS[e.etat] || e.etat || '',
    e.criticiteNiveau ? EQUIPMENT_CRITICITE_LABELS[e.criticiteNiveau] : '', e.criticiteScore ?? '', e.numeroSerie || '', e.marque || '', e.modele || '',
    equipmentNextDueDate(e) ? equipmentNextDueDate(e).toLocaleDateString('fr-FR') : '',
  ]);
  return [header, ...rows];
}
function exportEquipmentExcel(list) {
  downloadWorkbook([['Registre équipements', equipmentExportRows(list)]], `registre_equipements_${new Date().toISOString().slice(0, 10)}.xlsx`);
}
function exportEquipmentCsv(list) {
  downloadCsv(equipmentExportRows(list), `registre_equipements_${new Date().toISOString().slice(0, 10)}.csv`);
}

function EquipmentPage() {
  const C = useTheme();
  const equipment = useCollection('/business/equipment');
  const dashboardQ = useCollection('/business/equipment-dashboard');
  const [showForm, setShowForm] = useState(false);
  const [detailId, setDetailId] = useState(null);
  const [filter, setFilter] = useState('TOUS');
  if (equipment.loading) return <LoadingPanel />;
  if (equipment.error) return <ErrorPanel message={equipment.error} onRetry={equipment.reload} />;
  const list = equipment.data || [];
  const filtered = list.filter((e) => {
    if (filter === 'TOUS') return true;
    if (filter === 'A_JOUR') return !equipmentIsOverdue(e) && !equipmentHasNonConformiteOuverte(e) && e.etat === 'ACTIF';
    if (filter === 'EN_RETARD') return equipmentIsOverdue(e);
    if (filter === 'NON_CONFORMES') return equipmentHasNonConformiteOuverte(e);
    if (filter === 'MAINTENANCE') return e.etat === 'EN_MAINTENANCE';
    if (filter === 'HORS_SERVICE') return ['HORS_SERVICE', 'CONSIGNE', 'REFORME', 'MIS_AU_REBUT'].includes(e.etat);
    if (filter === 'CRITIQUES') return e.criticiteNiveau === 'CRITIQUE';
    return true;
  });
  const dash = dashboardQ.data;
  const [showAnalytics, setShowAnalytics] = useState(false);
  return (
    <div className="space-y-6">
      {showForm && <EquipmentForm onClose={() => setShowForm(false)} onCreated={() => { equipment.reload(); dashboardQ.reload(); }} />}
      {detailId && <EquipmentDetailModal equipmentId={detailId} onClose={() => setDetailId(null)} onChanged={() => { equipment.reload(); dashboardQ.reload(); }} />}
      <div className="flex items-center justify-between">
        <LiveBadge />
        <div className="flex gap-2">
          <button onClick={() => setShowAnalytics((v) => !v)} className="px-3 py-1.5 rounded-lg text-xs font-medium" style={{ backgroundColor: showAnalytics ? C.blue : C.cardAlt, color: showAnalytics ? '#fff' : C.text, border: `1px solid ${C.border}` }}>{showAnalytics ? 'Masquer les analytics' : 'Analytics avancées'}</button>
          <button onClick={() => setShowForm(true)} className="px-3 py-1.5 rounded-lg text-xs font-medium" style={{ backgroundColor: C.green, color: '#052e1f' }}>+ Nouvel équipement</button>
        </div>
      </div>
      <div className="flex flex-wrap gap-3">
        <KpiCard label="Équipements" value={list.length} color={C.blue} icon={Cog} />
        <KpiCard label="En retard" value={list.filter(equipmentIsOverdue).length} color={C.red} icon={AlertTriangle} />
        <KpiCard label="Non conformes" value={list.filter(equipmentHasNonConformiteOuverte).length} color={C.amber} icon={FileWarning} />
        <KpiCard label="Critiques" value={list.filter((e) => e.criticiteNiveau === 'CRITIQUE').length} color={C.red} icon={Shield} />
        <KpiCard label="Hors service" value={list.filter((e) => ['HORS_SERVICE', 'CONSIGNE', 'REFORME', 'MIS_AU_REBUT'].includes(e.etat)).length} color={C.textMuted} icon={Wrench} />
      </div>
      {showAnalytics && dash && (
        <div className="space-y-4">
          <div className="flex flex-wrap gap-3">
            <KpiCard label="Taux de disponibilité" value={dash.tauxDisponibilite != null ? `${dash.tauxDisponibilite}%` : '—'} color={C.green} icon={CheckCircle2} />
            <KpiCard label="Indice de conformité" value={dash.indiceConformite != null ? `${dash.indiceConformite}%` : '—'} color={C.blue} icon={ShieldCheck} />
            <KpiCard label="Échéances en retard" value={dash.enRetard} color={C.red} icon={AlertTriangle} />
            <KpiCard label="Critiques avec NC ouverte" value={dash.critiquesNonTraites} color={C.red} icon={FileWarning} />
            <KpiCard label="Coût maintenance" value={`${dash.coutTotalMaintenance.toLocaleString('fr-FR')} FCFA`} color={C.amber} icon={Wrench} />
            <KpiCard label="Coût étalonnage + contrôles" value={`${(dash.coutTotalEtalonnage + dash.coutTotalControles).toLocaleString('fr-FR')} FCFA`} color={C.amber} icon={ClipboardCheck} />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <Panel title="Répartition par état">
              <DonutChart data={Object.entries(dash.parEtat).map(([k, v]) => ({ name: EQUIPMENT_ETAT_LABELS[k] || k, value: v }))} colors={[C.green, C.blue, C.amber, C.red, C.textMuted, C.red, C.textMuted, C.textMuted]} />
            </Panel>
            <Panel title="Répartition par criticité">
              <DonutChart data={Object.entries(dash.parCriticite).map(([k, v]) => ({ name: EQUIPMENT_CRITICITE_LABELS[k] || k, value: v }))} colors={[C.textMuted, C.blue, C.amber, C.red]} />
            </Panel>
          </div>
          <Panel title="Top 5 des coûts de maintenance">
            {dash.topCouts.length
              ? <DataTable columns={['Équipement', 'Coût cumulé']} rows={dash.topCouts.map((t) => [`${t.code} — ${t.name}`, `${t.total.toLocaleString('fr-FR')} FCFA`])} />
              : <p className="text-sm text-center py-4" style={{ color: C.textMuted }}>Aucun coût de maintenance enregistré</p>}
          </Panel>
        </div>
      )}
      <div className="flex flex-wrap gap-2">
        {[['TOUS', 'Tous'], ['A_JOUR', 'À jour'], ['EN_RETARD', 'En retard'], ['NON_CONFORMES', 'Non conformes'], ['MAINTENANCE', 'Maintenance'], ['HORS_SERVICE', 'Hors service'], ['CRITIQUES', 'Critiques']].map(([id, label]) => (
          <button key={id} onClick={() => setFilter(id)} className="px-3 py-1.5 rounded-lg text-xs font-medium" style={{ backgroundColor: filter === id ? C.blue : C.cardAlt, color: filter === id ? '#fff' : C.textMuted, border: `1px solid ${C.border}` }}>{label}</button>
        ))}
      </div>
      <Panel title="Registre des équipements" subtitle={`${filtered.length} équipement(s)`} right={
        <div className="flex gap-2">
          <button onClick={() => exportEquipmentExcel(filtered)} className="flex items-center gap-1.5 text-xs px-2 py-1.5 rounded-lg" style={{ backgroundColor: C.cardAlt, border: `1px solid ${C.border}`, color: C.text }}><Download size={14} /> Excel</button>
          <button onClick={() => exportEquipmentCsv(filtered)} className="flex items-center gap-1.5 text-xs px-2 py-1.5 rounded-lg" style={{ backgroundColor: C.cardAlt, border: `1px solid ${C.border}`, color: C.text }}><Download size={14} /> CSV</button>
          <button onClick={() => window.print()} className="flex items-center gap-1.5 text-xs px-2 py-1.5 rounded-lg" style={{ backgroundColor: C.green, color: '#052e1f' }}><Printer size={14} /> Imprimer / PDF</button>
        </div>
      }>
        {filtered.length
          ? <DataTable columns={['Code', 'Équipement', 'Catégorie', 'Site', 'Responsable', 'État', 'Criticité', 'Prochaine échéance']}
              rows={filtered.map((e) => [
                e.code, e.name, e.categoryEq?.label || e.category || '—', e.site?.name || '—', e.responsable ? `${e.responsable.firstName} ${e.responsable.lastName}` : '—',
                <span className="text-xs font-medium px-2 py-0.5 rounded-full" style={{ backgroundColor: `${equipmentEtatColor(C, e.etat)}22`, color: equipmentEtatColor(C, e.etat) }}>{EQUIPMENT_ETAT_LABELS[e.etat] || e.etat}</span>,
                e.criticiteNiveau ? <span className="text-xs font-medium px-2 py-0.5 rounded-full" style={{ backgroundColor: `${equipmentCriticiteColor(C, e.criticiteNiveau)}22`, color: equipmentCriticiteColor(C, e.criticiteNiveau) }}>{EQUIPMENT_CRITICITE_LABELS[e.criticiteNiveau]}</span> : '—',
                equipmentNextDueDate(e) ? <span style={{ color: equipmentIsOverdue(e) ? C.red : C.text }}>{equipmentNextDueDate(e).toLocaleDateString('fr-FR')}</span> : '—',
              ])} onRowClick={(i) => setDetailId(filtered[i].id)} />
          : <p className="text-sm text-center py-6" style={{ color: C.textMuted }}>Aucun équipement pour ce filtre</p>}
      </Panel>
    </div>
  );
}

// ============================================================================
// QUART D'HEURE SÉCURITÉ — étiquettes/couleurs partagées entre les onglets.
// ============================================================================
const ST_STATUS_LABEL = { DRAFT: 'Brouillon', APPROVED: 'Approuvé', DELIVERED: 'Réalisé', ANNULE: 'Annulé', REPORTE: 'Reporté' };
function stStatusColor(C, s) { return { DRAFT: C.textMuted, APPROVED: C.blue, DELIVERED: C.green, ANNULE: C.red, REPORTE: C.amber }[s] || C.textMuted; }
const ST_PRIORITE_LABEL = { CRITIQUE: 'Critique', ELEVEE: 'Élevée', MOYENNE: 'Moyenne', FAIBLE: 'Faible' };
function stPrioriteColor(C, p) { return { CRITIQUE: C.red, ELEVEE: C.amber, MOYENNE: C.blue, FAIBLE: C.textMuted }[p] || C.textMuted; }
const ST_FEEDBACK_TYPES = [
  ['DANGER', 'Danger observé'], ['SITUATION_DANGEREUSE', 'Situation dangereuse'], ['COMPORTEMENT_RISQUE', 'Comportement à risque'],
  ['EQUIPEMENT_DEFECTUEUX', 'Équipement défectueux'], ['EPI_MANQUANT', 'EPI manquant'], ['EPC_DEFAILLANT', 'EPC défaillant'],
  ['ORGANISATION', 'Organisation'], ['ANOMALIE', 'Anomalie'], ['PRESQUE_ACCIDENT', 'Presqu\'accident'], ['NC', 'Non-conformité'], ['AMELIORATION', 'Amélioration'],
];
function stFeedbackTypeLabel(t) { return (ST_FEEDBACK_TYPES.find(([v]) => v === t) || [])[1] || t; }
const ST_TRANSFORM_TARGETS = [
  ['ACTION', 'Créer une action CAPA'], ['NON_CONFORMITY', 'Créer une non-conformité'], ['SAFETY_EVENT', 'Créer une situation dangereuse'],
];
function stTransformTargetLabel(t) { return { ACTION: 'Action CAPA', NON_CONFORMITY: 'Non-conformité', SAFETY_EVENT: 'Situation dangereuse' }[t] || t; }

// Zone la plus visible de la page : les thèmes proposés par le moteur
// d'analyse, avec les 3 décisions humaines possibles ligne par ligne.
function RecommendationRow({ reco, onAccept, onDecide }) {
  const C = useTheme();
  const [busy, setBusy] = useState(false);
  async function run(fn) { setBusy(true); try { await fn(); } catch (err) { alert(err.message); } setBusy(false); }
  return (
    <div className="p-3 rounded-lg" style={{ backgroundColor: C.cardAlt, border: `1px solid ${stPrioriteColor(C, reco.priorite)}40` }}>
      <div className="flex items-start justify-between gap-3 flex-wrap">
        <div className="min-w-0">
          <div className="flex items-center gap-2 flex-wrap">
            <p className="text-sm font-semibold" style={{ color: C.text }}>{reco.theme}</p>
            <span className="text-[10px] px-2 py-0.5 rounded-full font-medium" style={{ backgroundColor: `${stPrioriteColor(C, reco.priorite)}22`, color: stPrioriteColor(C, reco.priorite) }}>{ST_PRIORITE_LABEL[reco.priorite] || reco.priorite}</span>
            <span className="text-[10px] px-2 py-0.5 rounded-full" style={{ backgroundColor: C.card, color: C.textMuted }}>{reco.sourceModules}</span>
            <span className="text-[10px]" style={{ color: C.textMuted }}>score {reco.score}</span>
          </div>
          <p className="text-xs mt-1" style={{ color: C.textMuted }}>{reco.motif}</p>
        </div>
        <div className="flex gap-2 flex-shrink-0">
          <button disabled={busy} onClick={() => run(onAccept)} className="text-xs px-2 py-1 rounded-lg font-medium" style={{ backgroundColor: C.green, color: '#052e1f', opacity: busy ? 0.7 : 1 }}>Accepter et générer la fiche</button>
          <button disabled={busy} onClick={() => run(() => onDecide('REPORTER'))} className="text-xs px-2 py-1 rounded-lg" style={{ backgroundColor: C.card, border: `1px solid ${C.border}`, color: C.text, opacity: busy ? 0.7 : 1 }}>Reporter</button>
          <button disabled={busy} onClick={() => run(() => onDecide('IGNORER'))} className="text-xs px-2 py-1 rounded-lg" style={{ backgroundColor: `${C.red}22`, color: C.red, opacity: busy ? 0.7 : 1 }}>Ignorer</button>
        </div>
      </div>
    </div>
  );
}

// Formulaire de création/édition manuelle — champs riches de la fiche
// complète (theme, objectif, contexte, points essentiels...), préremplissable
// depuis la bibliothèque de thèmes ("Utiliser ce thème").
function SafetyTalkFormModal({ record, prefillTheme, onClose, onSaved }) {
  const C = useTheme();
  const editing = !!record;
  const workUnitsQ = useCollection('/business/work-units');
  const usersQ = useCollection('/users');
  const [form, setForm] = useState({
    title: record?.title || prefillTheme?.titre || '',
    summary: record?.summary || prefillTheme?.objectif || '',
    theme: record?.theme || prefillTheme?.titre || '',
    objectif: record?.objectif || prefillTheme?.objectif || '',
    contexte: record?.contexte || '',
    risquesConcernes: record?.risquesConcernes || '',
    personnesExposees: record?.personnesExposees || '',
    messagePrincipal: record?.messagePrincipal || '',
    pointsEssentiels: record?.pointsEssentiels || prefillTheme?.pointsEssentiels || '',
    bonnesPratiques: record?.bonnesPratiques || prefillTheme?.bonnesPratiques || '',
    mauvaisesPratiques: record?.mauvaisesPratiques || prefillTheme?.mauvaisesPratiques || '',
    questions: record?.questions || prefillTheme?.questions || '',
    exemplesTerrain: record?.exemplesTerrain || '',
    mesuresPrevention: record?.mesuresPrevention || '',
    conduiteATenir: record?.conduiteATenir || '',
    conclusion: record?.conclusion || '',
    engagementAttendu: record?.engagementAttendu || '',
    priorite: record?.priorite || 'MOYENNE',
    service: record?.service || '', zone: record?.zone || '', equipe: record?.equipe || '',
    workUnitId: record?.workUnitId || '', responsableAnimationId: record?.responsableAnimationId || '',
    scheduledAt: record?.scheduledAt ? record.scheduledAt.slice(0, 16) : '', duree: record?.duree ?? '', frequence: record?.frequence || '',
  });
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState(null);

  async function submit(e) {
    e.preventDefault();
    if (!form.title.trim()) { setError('Le titre est obligatoire.'); return; }
    setSaving(true); setError(null);
    try {
      const payload = {
        ...form,
        duree: form.duree === '' ? null : Number(form.duree),
        workUnitId: form.workUnitId || null,
        responsableAnimationId: form.responsableAnimationId || null,
        scheduledAt: form.scheduledAt ? new Date(form.scheduledAt).toISOString() : null,
        summary: form.summary || form.title,
      };
      const result = editing ? await api.patch(`/safety-talks/${record.id}`, payload) : await api.post('/safety-talks', payload);
      onSaved(result.id); onClose();
    } catch (err) { setError(err.message); }
    setSaving(false);
  }

  const ta = (key, label) => (
    <FormField label={label}><textarea value={form[key]} onChange={(e) => setForm({ ...form, [key]: e.target.value })} rows={2} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
  );

  return (
    <Modal title={editing ? 'Modifier la fiche' : "Nouveau quart d'heure sécurité"} onClose={onClose} wide>
      <form onSubmit={submit}>
        <div className="grid grid-cols-2 gap-x-4">
          <FormField label="Titre *"><input value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
          <FormField label="Thème"><input value={form.theme} onChange={(e) => setForm({ ...form, theme: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
        </div>
        {ta('summary', 'Résumé')}
        {ta('objectif', 'Objectif')}
        <div className="grid grid-cols-2 gap-x-4">{ta('contexte', 'Contexte')}{ta('risquesConcernes', 'Risques concernés')}</div>
        <FormField label="Personnes exposées"><input value={form.personnesExposees} onChange={(e) => setForm({ ...form, personnesExposees: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
        {ta('messagePrincipal', 'Message principal')}
        {ta('pointsEssentiels', 'Points essentiels')}
        <div className="grid grid-cols-2 gap-x-4">{ta('bonnesPratiques', 'Bonnes pratiques')}{ta('mauvaisesPratiques', 'Mauvaises pratiques')}</div>
        {ta('questions', 'Questions à poser')}
        {ta('exemplesTerrain', 'Exemples terrain')}
        {ta('mesuresPrevention', 'Mesures de prévention')}
        {ta('conduiteATenir', 'Conduite à tenir')}
        <div className="grid grid-cols-2 gap-x-4">{ta('conclusion', 'Conclusion')}{ta('engagementAttendu', 'Engagement attendu')}</div>
        <div className="grid grid-cols-3 gap-x-4">
          <FormField label="Priorité">
            <select value={form.priorite} onChange={(e) => setForm({ ...form, priorite: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)}>
              {Object.entries(ST_PRIORITE_LABEL).map(([v, l]) => <option key={v} value={v}>{l}</option>)}
            </select>
          </FormField>
          <FormField label="Service"><input value={form.service} onChange={(e) => setForm({ ...form, service: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
          <FormField label="Zone"><input value={form.zone} onChange={(e) => setForm({ ...form, zone: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
        </div>
        <div className="grid grid-cols-3 gap-x-4">
          <FormField label="Équipe"><input value={form.equipe} onChange={(e) => setForm({ ...form, equipe: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
          <FormField label="Unité de travail">
            <select value={form.workUnitId} onChange={(e) => setForm({ ...form, workUnitId: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)}>
              <option value="">—</option>{(workUnitsQ.data || []).map((w) => <option key={w.id} value={w.id}>{w.name}</option>)}
            </select>
          </FormField>
          <FormField label="Responsable animation">
            <select value={form.responsableAnimationId} onChange={(e) => setForm({ ...form, responsableAnimationId: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)}>
              <option value="">—</option>{(usersQ.data || []).map((u) => <option key={u.id} value={u.id}>{u.firstName} {u.lastName}</option>)}
            </select>
          </FormField>
        </div>
        <div className="grid grid-cols-3 gap-x-4">
          <FormField label="Date et heure planifiées"><input type="datetime-local" value={form.scheduledAt} onChange={(e) => setForm({ ...form, scheduledAt: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
          <FormField label="Durée (minutes)"><input type="number" value={form.duree} onChange={(e) => setForm({ ...form, duree: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
          <FormField label="Fréquence"><input value={form.frequence} onChange={(e) => setForm({ ...form, frequence: e.target.value })} placeholder="ex : Hebdomadaire" className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
        </div>
        {error && <p className="text-xs mb-2" style={{ color: C.red }}>{error}</p>}
        <div className="flex gap-2 mt-3">
          <button type="button" onClick={onClose} className="flex-1 py-2 rounded-lg text-xs" style={{ backgroundColor: C.cardAlt, border: `1px solid ${C.border}`, color: C.text }}>Annuler</button>
          <button type="submit" disabled={saving} className="flex-1 py-2 rounded-lg text-xs font-medium" style={{ backgroundColor: C.blue, color: '#fff', opacity: saving ? 0.7 : 1 }}>{saving ? '…' : editing ? 'Enregistrer' : 'Créer la fiche'}</button>
        </div>
      </form>
    </Modal>
  );
}

// Section "Émargement" — présence réelle par collaborateur (pas un simple
// compteur), avec ajout individuel ou en masse et suppression.
function SafetyTalkParticipantsSection({ talkId, locked }) {
  const C = useTheme();
  const participantsQ = useCollection(`/safety-talks/${talkId}/participants`);
  const employeesQ = useCollection('/epi/employees');
  const [showAdd, setShowAdd] = useState(false);
  const [single, setSingle] = useState({ employeeId: '', present: true, signature: '' });
  const [bulkIds, setBulkIds] = useState([]);
  const [busy, setBusy] = useState(false);
  const list = participantsQ.data || [];
  const already = new Set(list.map((p) => p.employeeId).filter(Boolean));
  const candidates = (employeesQ.data || []).filter((e) => !already.has(e.id));

  async function addSingle() {
    if (!single.employeeId) return;
    setBusy(true);
    try { await api.post(`/safety-talks/${talkId}/participants`, single); setSingle({ employeeId: '', present: true, signature: '' }); participantsQ.reload(); }
    catch (err) { alert(err.message); }
    setBusy(false);
  }
  async function addBulk() {
    if (!bulkIds.length) return;
    setBusy(true);
    try { await api.post(`/safety-talks/${talkId}/participants/bulk`, { employeeIds: bulkIds }); setBulkIds([]); participantsQ.reload(); }
    catch (err) { alert(err.message); }
    setBusy(false);
  }
  async function removeOne(id) {
    if (!window.confirm('Retirer ce participant ?')) return;
    try { await api.del(`/safety-talks/participants/${id}`); participantsQ.reload(); }
    catch (err) { alert(err.message); }
  }

  return (
    <div className="mb-5">
      <div className="flex items-center justify-between mb-2">
        <p className="text-sm font-semibold" style={{ color: C.text }}>Émargement ({list.length})</p>
        {!locked && <button onClick={() => setShowAdd((s) => !s)} className="text-xs px-2 py-1 rounded-lg" style={{ backgroundColor: C.green, color: '#052e1f' }}>+ Ajouter des participants</button>}
      </div>
      {showAdd && !locked && (
        <div className="p-3 rounded-lg mb-3 space-y-3" style={{ backgroundColor: C.cardAlt, border: `1px solid ${C.border}` }}>
          <div>
            <p className="text-xs mb-1" style={{ color: C.textMuted }}>Ajout individuel (avec signature)</p>
            <div className="flex gap-2 flex-wrap items-center">
              <select value={single.employeeId} onChange={(e) => setSingle({ ...single, employeeId: e.target.value })} className="px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)}>
                <option value="">Sélectionner un collaborateur…</option>{candidates.map((e) => <option key={e.id} value={e.id}>{e.firstName} {e.lastName}</option>)}
              </select>
              <label className="flex items-center gap-1 text-xs" style={{ color: C.text }}><input type="checkbox" checked={single.present} onChange={(e) => setSingle({ ...single, present: e.target.checked })} />Présent</label>
              <input placeholder="Signature (texte/initiales)" value={single.signature} onChange={(e) => setSingle({ ...single, signature: e.target.value })} className="px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} />
              <button disabled={busy || !single.employeeId} onClick={addSingle} className="px-3 py-1.5 rounded-lg text-xs font-medium" style={{ backgroundColor: C.blue, color: '#fff', opacity: busy ? 0.7 : 1 }}>Ajouter</button>
            </div>
          </div>
          <div>
            <p className="text-xs mb-1" style={{ color: C.textMuted }}>Ajout en masse</p>
            <div className="max-h-32 overflow-y-auto p-2 rounded-lg" style={{ backgroundColor: C.card, border: `1px solid ${C.border}` }}>
              {candidates.map((e) => (
                <label key={e.id} className="flex items-center gap-2 text-xs py-0.5" style={{ color: C.text }}>
                  <input type="checkbox" checked={bulkIds.includes(e.id)} onChange={(ev) => setBulkIds(ev.target.checked ? [...bulkIds, e.id] : bulkIds.filter((id) => id !== e.id))} />
                  {e.firstName} {e.lastName}
                </label>
              ))}
              {candidates.length === 0 && <p className="text-xs" style={{ color: C.textMuted }}>Tous les collaborateurs sont déjà émargés</p>}
            </div>
            <button disabled={busy || !bulkIds.length} onClick={addBulk} className="mt-2 px-3 py-1.5 rounded-lg text-xs font-medium" style={{ backgroundColor: C.blue, color: '#fff', opacity: busy ? 0.7 : 1 }}>Ajouter {bulkIds.length || ''} sélectionné(s)</button>
          </div>
        </div>
      )}
      {list.length
        ? <div className="space-y-1.5">{list.map((p) => (
            <div key={p.id} className="flex items-center justify-between p-2 rounded-lg gap-2" style={{ backgroundColor: C.cardAlt }}>
              <span className="text-xs" style={{ color: C.text }}>{p.employee ? `${p.employee.firstName} ${p.employee.lastName}` : p.user ? `${p.user.firstName} ${p.user.lastName}` : '—'}{p.signature ? ` · signé : ${p.signature}` : ''}</span>
              <div className="flex items-center gap-2 flex-shrink-0">
                <StatusChip statut={p.present ? 'Conforme' : 'Non conforme'} />
                {!locked && <button onClick={() => removeOne(p.id)} className="text-[11px]" style={{ color: C.red }}>Retirer</button>}
              </div>
            </div>
          ))}</div>
        : <p className="text-xs" style={{ color: C.textMuted }}>Aucun participant émargé</p>}
    </div>
  );
}

// Section "Remontées terrain" — LE point le plus important après les
// recommandations : chaque remontée non traitée propose 3 transformations
// claires vers CAPA / NC / situation dangereuse, jamais automatique.
function SafetyTalkFeedbackSection({ talkId }) {
  const C = useTheme();
  const feedbacksQ = useCollection(`/safety-talks/${talkId}/feedbacks`);
  const [showAdd, setShowAdd] = useState(false);
  const [form, setForm] = useState({ type: 'DANGER', description: '', localisation: '', criticite: 'MOYENNE', commentaire: '', mesureImmediate: '' });
  const [transformingId, setTransformingId] = useState(null);
  const [busy, setBusy] = useState(false);
  const list = feedbacksQ.data || [];

  async function addFeedback(e) {
    e.preventDefault();
    if (!form.description.trim()) return;
    setBusy(true);
    try { await api.post(`/safety-talks/${talkId}/feedbacks`, form); setForm({ type: 'DANGER', description: '', localisation: '', criticite: 'MOYENNE', commentaire: '', mesureImmediate: '' }); setShowAdd(false); feedbacksQ.reload(); }
    catch (err) { alert(err.message); }
    setBusy(false);
  }
  async function transform(feedbackId, targetModule) {
    setBusy(true);
    try { await api.post(`/safety-talks/feedbacks/${feedbackId}/transform`, { targetModule }); setTransformingId(null); feedbacksQ.reload(); }
    catch (err) { alert(err.message); }
    setBusy(false);
  }

  return (
    <div className="mb-5">
      <div className="flex items-center justify-between mb-2">
        <p className="text-sm font-semibold" style={{ color: C.text }}>Remontées terrain ({list.length})</p>
        <button onClick={() => setShowAdd((s) => !s)} className="text-xs px-2 py-1 rounded-lg" style={{ backgroundColor: C.green, color: '#052e1f' }}>+ Ajouter une remontée</button>
      </div>
      {showAdd && (
        <form onSubmit={addFeedback} className="p-3 rounded-lg mb-3" style={{ backgroundColor: C.cardAlt, border: `1px solid ${C.border}` }}>
          <div className="grid grid-cols-2 gap-x-3">
            <FormField label="Type">
              <select value={form.type} onChange={(e) => setForm({ ...form, type: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)}>
                {ST_FEEDBACK_TYPES.map(([v, l]) => <option key={v} value={v}>{l}</option>)}
              </select>
            </FormField>
            <FormField label="Criticité">
              <select value={form.criticite} onChange={(e) => setForm({ ...form, criticite: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)}>
                {Object.entries(ST_PRIORITE_LABEL).map(([v, l]) => <option key={v} value={v}>{l}</option>)}
              </select>
            </FormField>
          </div>
          <FormField label="Description *"><textarea value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} rows={2} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
          <div className="grid grid-cols-2 gap-x-3">
            <FormField label="Localisation"><input value={form.localisation} onChange={(e) => setForm({ ...form, localisation: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
            <FormField label="Mesure immédiate prise"><input value={form.mesureImmediate} onChange={(e) => setForm({ ...form, mesureImmediate: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
          </div>
          <FormField label="Commentaire"><textarea value={form.commentaire} onChange={(e) => setForm({ ...form, commentaire: e.target.value })} rows={2} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
          <div className="flex gap-2">
            <button type="button" onClick={() => setShowAdd(false)} className="flex-1 py-2 rounded-lg text-xs" style={{ backgroundColor: C.card, border: `1px solid ${C.border}`, color: C.text }}>Annuler</button>
            <button type="submit" disabled={busy} className="flex-1 py-2 rounded-lg text-xs font-medium" style={{ backgroundColor: C.blue, color: '#fff', opacity: busy ? 0.7 : 1 }}>{busy ? '…' : 'Enregistrer'}</button>
          </div>
        </form>
      )}
      {list.length
        ? <div className="space-y-2">{list.map((f) => (
            <div key={f.id} className="p-2.5 rounded-lg" style={{ backgroundColor: C.cardAlt }}>
              <div className="flex items-start justify-between gap-2 flex-wrap">
                <div className="min-w-0">
                  <div className="flex items-center gap-2 flex-wrap">
                    <span className="text-xs font-semibold" style={{ color: C.text }}>{stFeedbackTypeLabel(f.type)}</span>
                    {f.criticite && <span className="text-[10px] px-1.5 py-0.5 rounded-full" style={{ backgroundColor: `${stPrioriteColor(C, f.criticite)}22`, color: stPrioriteColor(C, f.criticite) }}>{ST_PRIORITE_LABEL[f.criticite] || f.criticite}</span>}
                    {f.localisation && <span className="text-[10px]" style={{ color: C.textMuted }}>· {f.localisation}</span>}
                  </div>
                  <p className="text-xs mt-1" style={{ color: C.text }}>{f.description}</p>
                  {f.mesureImmediate && <p className="text-[11px] mt-0.5" style={{ color: C.textMuted }}>Mesure immédiate : {f.mesureImmediate}</p>}
                </div>
                {f.status === 'TRANSFORME'
                  ? <span className="text-[11px] px-2 py-1 rounded-lg flex-shrink-0" style={{ backgroundColor: `${C.green}22`, color: C.green }}>Transformé en {stTransformTargetLabel(f.transformedIntoModule)}</span>
                  : <button onClick={() => setTransformingId(transformingId === f.id ? null : f.id)} className="text-[11px] px-2 py-1 rounded-lg flex-shrink-0" style={{ backgroundColor: C.blue, color: '#fff' }}>Transformer</button>}
              </div>
              {transformingId === f.id && (
                <div className="flex gap-2 flex-wrap mt-2 pt-2" style={{ borderTop: `1px solid ${C.border}` }}>
                  {ST_TRANSFORM_TARGETS.map(([v, l]) => (
                    <button key={v} disabled={busy} onClick={() => transform(f.id, v)} className="text-xs px-2 py-1 rounded-lg" style={{ backgroundColor: C.card, border: `1px solid ${C.border}`, color: C.text, opacity: busy ? 0.7 : 1 }}>{l}</button>
                  ))}
                </div>
              )}
            </div>
          ))}</div>
        : <p className="text-xs" style={{ color: C.textMuted }}>Aucune remontée terrain enregistrée</p>}
    </div>
  );
}

// Section "Quiz" — soumission de résultats et statistiques agrégées.
function SafetyTalkQuizSection({ talkId, participants }) {
  const C = useTheme();
  const statsQ = useCollection(`/safety-talks/${talkId}/quiz-stats`);
  const [form, setForm] = useState({ participantId: '', score: '', total: '' });
  const [busy, setBusy] = useState(false);
  const stats = statsQ.data || {};

  async function submit(e) {
    e.preventDefault();
    if (form.score === '' || form.total === '') return;
    setBusy(true);
    try {
      await api.post(`/safety-talks/${talkId}/quiz`, { participantId: form.participantId || undefined, score: Number(form.score), total: Number(form.total) });
      setForm({ participantId: '', score: '', total: '' }); statsQ.reload();
    } catch (err) { alert(err.message); }
    setBusy(false);
  }

  return (
    <div className="mb-5">
      <p className="text-sm font-semibold mb-2" style={{ color: C.text }}>Quiz de compréhension</p>
      <div className="flex flex-wrap gap-3 mb-3">
        <KpiCard label="Participants au quiz" value={stats.participants ?? '—'} color={C.blue} icon={Users} />
        <KpiCard label="Score moyen" value={stats.scoreMoyen != null ? `${stats.scoreMoyen}%` : '—'} color={C.green} icon={Activity} />
        <KpiCard label="Taux de réussite" value={stats.tauxReussite != null ? `${stats.tauxReussite}%` : '—'} color={stats.tauxReussite >= 50 ? C.green : C.amber} icon={CheckCircle2} />
      </div>
      <form onSubmit={submit} className="flex gap-2 flex-wrap items-end">
        <FormField label="Participant (optionnel)">
          <select value={form.participantId} onChange={(e) => setForm({ ...form, participantId: e.target.value })} className="px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)}>
            <option value="">Anonyme</option>{(participants || []).map((p) => <option key={p.id} value={p.id}>{p.employee ? `${p.employee.firstName} ${p.employee.lastName}` : p.id}</option>)}
          </select>
        </FormField>
        <FormField label="Score"><input type="number" value={form.score} onChange={(e) => setForm({ ...form, score: e.target.value })} className="w-24 px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
        <FormField label="Total"><input type="number" value={form.total} onChange={(e) => setForm({ ...form, total: e.target.value })} className="w-24 px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
        <button type="submit" disabled={busy} className="px-3 py-2 rounded-lg text-xs font-medium mb-3" style={{ backgroundColor: C.blue, color: '#fff', opacity: busy ? 0.7 : 1 }}>Enregistrer le résultat</button>
      </form>
    </div>
  );
}

// Fiche détail — vue complète du quart d'heure sécurité : champs riches,
// workflow (approuver/planifier/reporter/annuler/diffuser selon statut),
// émargement, remontées terrain, quiz, et CAPA associées.
function SafetyTalkDetailModal({ talk, onClose, onChanged }) {
  const C = useTheme();
  const [editing, setEditing] = useState(false);
  const [showSchedule, setShowSchedule] = useState(false);
  const [scheduleForm, setScheduleForm] = useState({ scheduledAt: talk.scheduledAt ? talk.scheduledAt.slice(0, 16) : '', frequence: talk.frequence || '', duree: talk.duree ?? '' });
  const [busy, setBusy] = useState(false);
  const participantsQ = useCollection(`/safety-talks/${talk.id}/participants`);
  const locked = talk.status === 'DELIVERED' || talk.status === 'ANNULE';

  async function run(action) { setBusy(true); try { await action(); onChanged(); } catch (err) { alert(err.message); } setBusy(false); }
  const approve = () => run(() => api.post(`/safety-talks/${talk.id}/approve`, {}));
  const deliver = () => run(() => api.post(`/safety-talks/${talk.id}/deliver`, {}));
  const cancel = () => { if (window.confirm("Annuler ce quart d'heure sécurité ?")) run(() => api.post(`/safety-talks/${talk.id}/cancel`, {})); };
  const del = () => run(async () => { if (window.confirm(`Supprimer définitivement « ${talk.title} » ? Cette action est irréversible.`)) { await api.del(`/safety-talks/${talk.id}`); onClose(); } });
  async function submitSchedule(e) {
    e.preventDefault();
    if (!scheduleForm.scheduledAt) return;
    const payload = { scheduledAt: new Date(scheduleForm.scheduledAt).toISOString(), frequence: scheduleForm.frequence || undefined, duree: scheduleForm.duree === '' ? undefined : Number(scheduleForm.duree) };
    const endpoint = talk.scheduledAt ? 'postpone' : 'schedule';
    await run(() => api.post(`/safety-talks/${talk.id}/${endpoint}`, endpoint === 'postpone' ? { scheduledAt: payload.scheduledAt } : payload));
    setShowSchedule(false);
  }

  if (editing) return <SafetyTalkFormModal record={talk} onClose={() => setEditing(false)} onSaved={() => { onChanged(); setEditing(false); }} />;

  return (
    <Modal title={talk.title} onClose={onClose} wide>
      <div className="flex items-start justify-between mb-3 flex-wrap gap-2">
        <div>
          <p className="text-xs" style={{ color: C.textMuted }}>Semaine du {new Date(talk.weekStart).toLocaleDateString('fr-FR')}{talk.scheduledAt ? ` · Planifié le ${new Date(talk.scheduledAt).toLocaleString('fr-FR')}` : ' · Non planifié'}{talk.origineType === 'AUTO_RECOMMANDE' ? ' · Auto-recommandé' : ' · Créé manuellement'}</p>
          {talk.origineRaison && <p className="text-xs mt-0.5" style={{ color: C.textMuted }}>Origine : {talk.origineRaison}</p>}
        </div>
        <div className="flex items-center gap-2">
          {talk.priorite && <span className="text-xs font-medium" style={{ color: stPrioriteColor(C, talk.priorite) }}>{ST_PRIORITE_LABEL[talk.priorite] || talk.priorite}</span>}
          <StatusChip statut={ST_STATUS_LABEL[talk.status] || talk.status} />
        </div>
      </div>

      <div className="flex gap-2 flex-wrap mb-4">
        {!locked && <button onClick={() => setEditing(true)} className="text-xs px-2 py-1.5 rounded-lg" style={{ backgroundColor: C.cardAlt, border: `1px solid ${C.border}`, color: C.text }}>Modifier</button>}
        {talk.status === 'DRAFT' && <button disabled={busy} onClick={approve} className="text-xs px-2 py-1.5 rounded-lg font-medium" style={{ backgroundColor: C.blue, color: '#fff' }}>Approuver</button>}
        {talk.status === 'APPROVED' && <button disabled={busy} onClick={deliver} className="text-xs px-2 py-1.5 rounded-lg font-medium" style={{ backgroundColor: C.green, color: '#052e1f' }}>Marquer réalisé</button>}
        {!locked && <button disabled={busy} onClick={() => setShowSchedule((s) => !s)} className="text-xs px-2 py-1.5 rounded-lg" style={{ backgroundColor: C.cardAlt, border: `1px solid ${C.border}`, color: C.text }}>{talk.scheduledAt ? 'Reporter' : 'Planifier'}</button>}
        {!locked && <button disabled={busy} onClick={cancel} className="text-xs px-2 py-1.5 rounded-lg" style={{ backgroundColor: `${C.red}22`, color: C.red }}>Annuler la séance</button>}
        {talk.status !== 'DELIVERED' && <button disabled={busy} onClick={del} className="text-xs px-2 py-1.5 rounded-lg" style={{ backgroundColor: C.card, border: `1px solid ${C.border}`, color: C.textMuted }}>Supprimer</button>}
      </div>
      {showSchedule && (
        <form onSubmit={submitSchedule} className="p-3 rounded-lg mb-4 flex gap-2 flex-wrap items-end" style={{ backgroundColor: C.cardAlt, border: `1px solid ${C.border}` }}>
          <FormField label="Date et heure"><input type="datetime-local" required value={scheduleForm.scheduledAt} onChange={(e) => setScheduleForm({ ...scheduleForm, scheduledAt: e.target.value })} className="px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
          <FormField label="Durée (min)"><input type="number" value={scheduleForm.duree} onChange={(e) => setScheduleForm({ ...scheduleForm, duree: e.target.value })} className="w-24 px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
          <FormField label="Fréquence"><input value={scheduleForm.frequence} onChange={(e) => setScheduleForm({ ...scheduleForm, frequence: e.target.value })} className="px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
          <button type="submit" disabled={busy} className="px-3 py-2 rounded-lg text-xs font-medium mb-3" style={{ backgroundColor: C.blue, color: '#fff', opacity: busy ? 0.7 : 1 }}>Confirmer</button>
        </form>
      )}

      <div className="grid grid-cols-2 gap-4 mb-5">
        {talk.objectif && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Objectif</p><p className="text-sm whitespace-pre-line" style={{ color: C.text }}>{talk.objectif}</p></div>}
        {talk.contexte && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Contexte</p><p className="text-sm whitespace-pre-line" style={{ color: C.text }}>{talk.contexte}</p></div>}
        {talk.risquesConcernes && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Risques concernés</p><p className="text-sm whitespace-pre-line" style={{ color: C.text }}>{talk.risquesConcernes}</p></div>}
        {talk.personnesExposees && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Personnes exposées</p><p className="text-sm whitespace-pre-line" style={{ color: C.text }}>{talk.personnesExposees}</p></div>}
        {talk.messagePrincipal && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Message principal</p><p className="text-sm whitespace-pre-line" style={{ color: C.text }}>{talk.messagePrincipal}</p></div>}
        {talk.pointsEssentiels && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Points essentiels</p><p className="text-sm whitespace-pre-line" style={{ color: C.text }}>{talk.pointsEssentiels}</p></div>}
        {talk.bonnesPratiques && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Bonnes pratiques</p><p className="text-sm whitespace-pre-line" style={{ color: C.text }}>{talk.bonnesPratiques}</p></div>}
        {talk.mauvaisesPratiques && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Mauvaises pratiques</p><p className="text-sm whitespace-pre-line" style={{ color: C.text }}>{talk.mauvaisesPratiques}</p></div>}
        {talk.questions && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Questions à poser</p><p className="text-sm whitespace-pre-line" style={{ color: C.text }}>{talk.questions}</p></div>}
        {talk.exemplesTerrain && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Exemples terrain</p><p className="text-sm whitespace-pre-line" style={{ color: C.text }}>{talk.exemplesTerrain}</p></div>}
        {talk.mesuresPrevention && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Mesures de prévention</p><p className="text-sm whitespace-pre-line" style={{ color: C.text }}>{talk.mesuresPrevention}</p></div>}
        {talk.conduiteATenir && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Conduite à tenir</p><p className="text-sm whitespace-pre-line" style={{ color: C.text }}>{talk.conduiteATenir}</p></div>}
        {talk.conclusion && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Conclusion</p><p className="text-sm whitespace-pre-line" style={{ color: C.text }}>{talk.conclusion}</p></div>}
        {talk.engagementAttendu && <div><p className="text-xs font-semibold" style={{ color: C.textMuted }}>Engagement attendu</p><p className="text-sm whitespace-pre-line" style={{ color: C.text }}>{talk.engagementAttendu}</p></div>}
      </div>
      <p className="text-xs mb-5" style={{ color: C.textMuted }}>{[talk.service, talk.zone, talk.equipe].filter(Boolean).join(' · ') || null}</p>

      <SafetyTalkParticipantsSection talkId={talk.id} locked={locked} />
      <SafetyTalkFeedbackSection talkId={talk.id} />
      <SafetyTalkQuizSection talkId={talk.id} participants={participantsQ.data || []} />
      <CapaLinksPanel sourceModule="SAFETY_TALK" sourceEntityId={talk.id} />
    </Modal>
  );
}

// Onglet "Paramètres" — CRUD des règles configurables du moteur de
// recommandation (seuils, périodes d'analyse).
function SafetyTalkRulesPanel({ rulesQ }) {
  const C = useTheme();
  const [form, setForm] = useState({ code: '', label: '', seuil: '', periodeJours: '', active: true });
  const [busy, setBusy] = useState(false);
  const list = rulesQ.data || [];

  async function submit(e) {
    e.preventDefault();
    if (!form.code.trim() || !form.label.trim()) return;
    setBusy(true);
    try {
      await api.post('/safety-talks/rules', { ...form, seuil: form.seuil === '' ? undefined : Number(form.seuil), periodeJours: form.periodeJours === '' ? undefined : Number(form.periodeJours) });
      setForm({ code: '', label: '', seuil: '', periodeJours: '', active: true }); rulesQ.reload();
    } catch (err) { alert(err.message); }
    setBusy(false);
  }
  async function del(r) { await confirmAndDelete(r.label, `/safety-talks/rules/${r.id}`, () => rulesQ.reload()); }
  async function toggle(r) {
    try { await api.post('/safety-talks/rules', { code: r.code, label: r.label, seuil: r.seuil, periodeJours: r.periodeJours, active: !r.active }); rulesQ.reload(); }
    catch (err) { alert(err.message); }
  }

  return (
    <div className="space-y-4">
      <Panel title="Nouvelle règle de déclenchement">
        <form onSubmit={submit} className="grid grid-cols-2 md:grid-cols-5 gap-3 items-end">
          <FormField label="Code *"><input value={form.code} onChange={(e) => setForm({ ...form, code: e.target.value })} placeholder="ex : FENETRE_ANALYSE_JOURS" className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
          <FormField label="Libellé *"><input value={form.label} onChange={(e) => setForm({ ...form, label: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
          <FormField label="Seuil"><input type="number" value={form.seuil} onChange={(e) => setForm({ ...form, seuil: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
          <FormField label="Période (jours)"><input type="number" value={form.periodeJours} onChange={(e) => setForm({ ...form, periodeJours: e.target.value })} className="w-full px-3 py-2 rounded-lg text-sm outline-none" style={inputStyle(C)} /></FormField>
          <button type="submit" disabled={busy} className="px-3 py-2 rounded-lg text-xs font-medium mb-3" style={{ backgroundColor: C.blue, color: '#fff', opacity: busy ? 0.7 : 1 }}>Enregistrer</button>
        </form>
      </Panel>
      <Panel title="Règles configurées" subtitle={`${list.length} règle(s)`}>
        {list.length
          ? <div className="space-y-1.5">{list.map((r) => (
              <div key={r.id} className="flex items-center justify-between p-2 rounded-lg gap-2 flex-wrap" style={{ backgroundColor: C.cardAlt }}>
                <div>
                  <p className="text-xs font-semibold" style={{ color: C.text }}>{r.label}</p>
                  <p className="text-[11px]" style={{ color: C.textMuted }}>{r.code}{r.seuil != null ? ` · seuil ${r.seuil}` : ''}{r.periodeJours != null ? ` · période ${r.periodeJours} j` : ''}</p>
                </div>
                <div className="flex items-center gap-2">
                  <button onClick={() => toggle(r)} className="text-[11px] px-2 py-0.5 rounded-full" style={{ backgroundColor: r.active ? `${C.green}22` : `${C.textMuted}22`, color: r.active ? C.green : C.textMuted }}>{r.active ? 'Active' : 'Inactive'}</button>
                  <button onClick={() => del(r)} className="text-[11px]" style={{ color: C.red }}>Supprimer</button>
                </div>
              </div>
            ))}</div>
          : <p className="text-sm text-center py-6" style={{ color: C.textMuted }}>Aucune règle configurée — les valeurs par défaut du moteur s'appliquent</p>}
      </Panel>
    </div>
  );
}

function SafetyTalkPage() {
  const C = useTheme();
  const [tab, setTab] = useState('apercu');
  const dashboardQ = useCollection('/safety-talks/dashboard');
  const recommendationsQ = useCollection('/safety-talks/recommendations');
  const talksQ = useCollection('/safety-talks');
  const libraryQ = useCollection('/safety-talks/library');
  const matriceQ = useCollection('/safety-talks/matrice');
  const rulesQ = useCollection('/safety-talks/rules');
  const [statusFilter, setStatusFilter] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [formPrefill, setFormPrefill] = useState(null);
  const [detailId, setDetailId] = useState(null);
  const [refreshing, setRefreshing] = useState(false);
  const [recoError, setRecoError] = useState(null);

  function reloadAll() { dashboardQ.reload(); recommendationsQ.reload(); talksQ.reload(); matriceQ.reload(); }

  async function refreshRecommendations() {
    setRefreshing(true); setRecoError(null);
    try { await api.post('/safety-talks/recommendations/refresh', {}); recommendationsQ.reload(); dashboardQ.reload(); }
    catch (err) { setRecoError(err.message); }
    setRefreshing(false);
  }
  async function decide(id, decision) { await api.post(`/safety-talks/recommendations/${id}/decision`, { decision }); recommendationsQ.reload(); }
  async function acceptAndGenerate(reco) {
    const created = await api.post(`/safety-talks/recommendations/${reco.id}/generate`, {});
    recommendationsQ.reload(); dashboardQ.reload(); matriceQ.reload();
    await talksQ.reload();
    setDetailId(created.id); setTab('seances');
  }

  const talks = talksQ.data || [];
  const filteredTalks = statusFilter ? talks.filter((t) => t.status === statusFilter) : talks;
  const upcoming = talks.filter((t) => t.scheduledAt && new Date(t.scheduledAt) >= new Date() && !['DELIVERED', 'ANNULE'].includes(t.status))
    .sort((a, b) => new Date(a.scheduledAt) - new Date(b.scheduledAt)).slice(0, 6);
  const recos = recommendationsQ.data || [];
  const dash = dashboardQ.data || {};
  const selectedTalk = detailId ? talks.find((t) => t.id === detailId) : null;

  return (
    <div className="space-y-6">
      {showForm && <SafetyTalkFormModal prefillTheme={formPrefill} onClose={() => { setShowForm(false); setFormPrefill(null); }} onSaved={(id) => { reloadAll(); setDetailId(id); setTab('seances'); }} />}
      {selectedTalk && <SafetyTalkDetailModal talk={selectedTalk} onClose={() => setDetailId(null)} onChanged={reloadAll} />}

      <div className="flex flex-wrap gap-2">
        {[['apercu', "Vue d'ensemble"], ['seances', 'Séances'], ['bibliotheque', 'Bibliothèque de thèmes'], ['matrice', 'Matrice'], ['parametres', 'Paramètres']].map(([id, label]) => (
          <button key={id} onClick={() => setTab(id)} className="px-3 py-1.5 rounded-lg text-xs font-medium" style={{ backgroundColor: tab === id ? C.blue : 'transparent', color: tab === id ? '#fff' : C.textMuted }}>{label}</button>
        ))}
      </div>

      {tab === 'apercu' && (
        dashboardQ.loading ? <LoadingPanel /> : dashboardQ.error ? <ErrorPanel message={dashboardQ.error} onRetry={dashboardQ.reload} /> : (
          <div className="space-y-6">
            <LiveBadge />
            <div className="flex flex-wrap gap-3">
              <KpiCard label="Planifiés" value={dash.planifies ?? '—'} color={C.blue} icon={ClipboardList} />
              <KpiCard label="Réalisés" value={dash.realises ?? '—'} color={C.green} icon={CheckCircle2} />
              <KpiCard label="En retard" value={dash.enRetard ?? '—'} color={dash.enRetard > 0 ? C.red : C.green} icon={AlertTriangle} />
              <KpiCard label="Annulés" value={dash.annules ?? '—'} color={C.textMuted} icon={X} />
              <KpiCard label="Taux de réalisation" value={dash.tauxRealisation != null ? `${dash.tauxRealisation}%` : '—'} color={C.green} icon={Activity} />
              <KpiCard label="Participants" value={dash.participants ?? '—'} color={C.blue} icon={Users} />
              <KpiCard label="Taux de participation" value={dash.tauxParticipation != null ? `${dash.tauxParticipation}%` : '—'} color={C.blue} icon={Users} />
            </div>
            <div className="flex flex-wrap gap-3">
              <KpiCard label="Thèmes traités" value={dash.themesTraites ?? '—'} color={C.blue} icon={BookOpen} />
              <KpiCard label="Remontées terrain" value={dash.remonteesTerrain ?? '—'} color={C.amber} icon={FileWarning} />
              <KpiCard label="Dangers détectés" value={dash.dangersDetectes ?? '—'} color={C.red} icon={AlertTriangle} />
              <KpiCard label="Actions créées" value={dash.actionsCreees ?? '—'} color={C.blue} icon={ClipboardCheck} />
              <KpiCard label="Actions clôturées" value={dash.actionsClotures ?? '—'} color={C.green} icon={CheckCircle2} />
              <KpiCard label="Actions en retard" value={dash.actionsEnRetard ?? '—'} color={dash.actionsEnRetard > 0 ? C.red : C.green} icon={AlertTriangle} />
            </div>
            <div className="flex flex-wrap gap-3">
              <KpiCard label="Sujets auto-générés" value={dash.sujetsAutoGeneres ?? '—'} color={C.blue} icon={RefreshCw} />
              <KpiCard label="Sensibilisations accidents" value={dash.sensibilisationsAccidents ?? '—'} color={C.red} icon={HardHat} />
              <KpiCard label="Sensibilisations NC" value={dash.sensibilisationsNc ?? '—'} color={C.amber} icon={FileWarning} />
              <KpiCard label="Sensibilisations risques" value={dash.sensibilisationsRisques ?? '—'} color={C.blue} icon={Shield} />
            </div>

            <Panel title="Thèmes recommandés" subtitle="Proposés par le moteur d'analyse à partir des accidents, non-conformités, risques et actions en retard des autres modules QHSE"
              right={<button onClick={refreshRecommendations} disabled={refreshing} className="px-3 py-1.5 rounded-lg text-xs font-medium flex items-center gap-1" style={{ backgroundColor: C.cardAlt, border: `1px solid ${C.border}`, color: C.text, opacity: refreshing ? 0.7 : 1 }}><RefreshCw size={12} className={refreshing ? 'animate-spin' : ''} />{refreshing ? 'Analyse…' : "Actualiser l'analyse"}</button>}>
              {recoError && <p className="text-xs mb-2" style={{ color: C.red }}>{recoError}</p>}
              {recos.length === 0
                ? <p className="text-sm text-center py-6" style={{ color: C.textMuted }}>Aucune recommandation en attente — cliquez sur « Actualiser l'analyse » pour lancer le moteur.</p>
                : <div className="space-y-2">{recos.map((r) => <RecommendationRow key={r.id} reco={r} onAccept={() => acceptAndGenerate(r)} onDecide={(d) => decide(r.id, d)} />)}</div>}
            </Panel>

            <Panel title="Prochaines séances planifiées">
              {upcoming.length === 0
                ? <p className="text-sm text-center py-6" style={{ color: C.textMuted }}>Aucune séance planifiée à venir</p>
                : <div className="space-y-1.5">{upcoming.map((t) => (
                    <div key={t.id} onClick={() => setDetailId(t.id)} className="flex items-center justify-between p-2 rounded-lg cursor-pointer" style={{ backgroundColor: C.cardAlt }}>
                      <div><span className="text-sm" style={{ color: C.text }}>{t.title}</span><span className="text-xs ml-2" style={{ color: C.textMuted }}>{new Date(t.scheduledAt).toLocaleString('fr-FR')}</span></div>
                      <StatusChip statut={ST_STATUS_LABEL[t.status] || t.status} />
                    </div>
                  ))}</div>}
            </Panel>
          </div>
        )
      )}

      {tab === 'seances' && (
        <div className="space-y-4">
          <div className="flex items-center justify-between flex-wrap gap-2">
            <LiveBadge />
            <div className="flex items-center gap-2">
              <select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)} className="px-3 py-1.5 rounded-lg text-xs outline-none" style={inputStyle(C)}>
                <option value="">Statut — tous</option>{Object.entries(ST_STATUS_LABEL).map(([v, l]) => <option key={v} value={v}>{l}</option>)}
              </select>
              <button onClick={() => { setFormPrefill(null); setShowForm(true); }} className="px-3 py-1.5 rounded-lg text-xs font-medium" style={{ backgroundColor: C.green, color: '#052e1f' }}>+ Nouvelle séance</button>
            </div>
          </div>
          {talksQ.loading ? <LoadingPanel /> : talksQ.error ? <ErrorPanel message={talksQ.error} onRetry={talksQ.reload} /> : (
            filteredTalks.length === 0
              ? <p className="text-sm text-center py-6" style={{ color: C.textMuted }}>Aucun quart d'heure sécurité pour ce filtre</p>
              : <div className="space-y-2">{filteredTalks.map((t) => (
                  <Panel key={t.id} className="cursor-pointer" onClick={() => setDetailId(t.id)}>
                    <div className="flex items-start justify-between flex-wrap gap-2">
                      <div>
                        <p className="text-sm font-semibold" style={{ color: C.text }}>{t.title}</p>
                        <p className="text-xs" style={{ color: C.textMuted }}>Semaine du {new Date(t.weekStart).toLocaleDateString('fr-FR')}{t.scheduledAt ? ` · Planifié le ${new Date(t.scheduledAt).toLocaleString('fr-FR')}` : ''}{t.origineType === 'AUTO_RECOMMANDE' ? ' · Auto-recommandé' : ''}</p>
                      </div>
                      <div className="flex items-center gap-2">
                        {t.priorite && <span className="text-xs font-medium" style={{ color: stPrioriteColor(C, t.priorite) }}>{ST_PRIORITE_LABEL[t.priorite] || t.priorite}</span>}
                        <StatusChip statut={ST_STATUS_LABEL[t.status] || t.status} />
                      </div>
                    </div>
                  </Panel>
                ))}</div>
          )}
        </div>
      )}

      {tab === 'bibliotheque' && (
        libraryQ.loading ? <LoadingPanel /> : libraryQ.error ? <ErrorPanel message={libraryQ.error} onRetry={libraryQ.reload} /> : (
          <div className="space-y-4">
            <LiveBadge />
            {(libraryQ.data || []).map((cat) => (
              <Panel key={cat.categorie} title={cat.categorie}>
                <div className="space-y-3">
                  {cat.themes.map((th, i) => (
                    <div key={i} className="p-3 rounded-lg" style={{ backgroundColor: C.cardAlt }}>
                      <div className="flex items-start justify-between gap-2">
                        <div>
                          <p className="text-sm font-semibold" style={{ color: C.text }}>{th.titre}</p>
                          <p className="text-xs mt-0.5" style={{ color: C.textMuted }}>{th.objectif}</p>
                        </div>
                        <button onClick={() => { setFormPrefill(th); setShowForm(true); }} className="text-xs px-2 py-1 rounded-lg flex-shrink-0" style={{ backgroundColor: C.blue, color: '#fff' }}>Utiliser ce thème</button>
                      </div>
                    </div>
                  ))}
                </div>
              </Panel>
            ))}
          </div>
        )
      )}

      {tab === 'matrice' && (
        matriceQ.loading ? <LoadingPanel /> : matriceQ.error ? <ErrorPanel message={matriceQ.error} onRetry={matriceQ.reload} /> : (
          <Panel title="Matrice de traçabilité" subtitle={`${(matriceQ.data || []).length} recommandation(s) transformée(s) en séance`}>
            {(matriceQ.data || []).length
              ? <DataTable columns={['Source', 'Événement(s)', 'Risque(s)', 'Thème', 'Priorité', 'Statut']}
                  rows={(matriceQ.data || []).map((m) => [m.source, m.evenement || '—', m.risque || '—', m.theme, ST_PRIORITE_LABEL[m.priorite] || m.priorite || '—', ST_STATUS_LABEL[m.statut] || m.statut])} />
              : <p className="text-sm text-center py-6" style={{ color: C.textMuted }}>Aucune ligne dans la matrice</p>}
          </Panel>
        )
      )}

      {tab === 'parametres' && <SafetyTalkRulesPanel rulesQ={rulesQ} />}
    </div>
  );
}

const PAGES = {
  pilotage: PilotagePage, 'qualite-controles': QualiteControlesPage, 'qualite-processus': QualiteProcessusPage, 'qualite-indicateurs': IndicateursQualitePage, 'qualite-reclamations': QualiteReclamationsPage, 'qualite-fournisseurs': QualiteFournisseursPage,
  'securite-accidents': SecuriteAccidentsPage, 'securite-epi': SecuriteEpiPage, 'securite-hygiene': SecuriteHygienePage,
  environnement: EnvironnementPage, risques: RisquesPage, audits: AuditsPage, 'non-conformites': NonConformitesPage, capa: CapaPage,
  documentation: DocumentationPage, 'quart-heure-securite': SafetyTalkPage, haccp: HaccpPage, equipements: EquipmentPage, veille: VeilleReglementairePage, objectifs: ObjectifsPage, rapports: RapportsPage, utilisateurs: UtilisateursPage,
};

// ============================================================================
// Application
// ============================================================================
export default function QhseDashboard() {
  const [user, setUser] = useState(getStoredUser());
  const [page, setPage] = useState('pilotage');
  const [themeMode, setThemeMode] = useState('dark');
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [showChangePassword, setShowChangePassword] = useState(false);
  const C = THEMES[themeMode];
  const actionsForBadge = useCollection(user ? '/business/actions' : null);
  const capaStats = computeCapaStatsReal(actionsForBadge.data || []);
  const PageComponent = PAGES[page] || PilotagePage;

  // Si le rafraîchissement automatique finit par échouer (jeton de 30 jours
  // expiré, ou révoqué depuis un autre appareil), on ramène proprement à
  // l'écran de connexion plutôt que de laisser l'application dans un état
  // bloqué avec des erreurs partout.
  useEffect(() => {
    const onExpired = () => setUser(null);
    window.addEventListener('qhse:session-expired', onExpired);
    return () => window.removeEventListener('qhse:session-expired', onExpired);
  }, []);

  if (!user) {
    return <LoginPage onLoggedIn={setUser} />;
  }

  async function logout() {
    await apiLogout();
    setUser(null);
  }

  return (
    <ThemeContext.Provider value={C}>
      <div className="flex min-h-screen relative" style={{ backgroundColor: C.bg, fontFamily: 'Inter, system-ui, sans-serif' }}>
        {showChangePassword && <ChangeMyPasswordForm email={user.email} onClose={() => setShowChangePassword(false)} />}
        {sidebarOpen && (
          <div className="fixed inset-0 bg-black/50 z-20 md:hidden" onClick={() => setSidebarOpen(false)} />
        )}
        <aside
          className={`w-64 shrink-0 p-4 border-r overflow-y-auto fixed md:static inset-y-0 left-0 z-30 transition-transform duration-200 flex flex-col ${sidebarOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}`}
          style={{ borderColor: C.border, backgroundColor: C.bg }}
        >
          <div className="flex items-center justify-between gap-2 mb-6 px-2">
            <div className="flex items-center gap-2">
              <div className="w-9 h-9 rounded-lg flex items-center justify-center shrink-0" style={{ backgroundColor: C.blue }}><ShieldCheck size={20} color="#fff" /></div>
              <div>
                <div className="text-sm font-semibold" style={{ color: C.text }}>Gestion QHSE 360</div>
                <div className="text-[10px]" style={{ color: C.textMuted }}>Qualité · Sécurité · Hygiène · Environnement</div>
              </div>
            </div>
            <button className="md:hidden p-1" onClick={() => setSidebarOpen(false)}><X size={18} color={C.textMuted} /></button>
          </div>
          <div className="flex-1">
            {NAV_GROUPS.map((group) => (
              <div key={group.label} className="mb-4">
                <div className="px-3 mb-1 text-[10px] font-semibold tracking-wide" style={{ color: C.textMuted }}>{group.label}</div>
                <nav className="space-y-0.5">
                  {group.items.map((item) => {
                    const active = page === item.id, Icon = item.icon;
                    return (
                      <button key={item.id} onClick={() => { setPage(item.id); setSidebarOpen(false); }} className="w-full flex items-center gap-3 px-3 py-2 rounded-lg text-sm text-left transition-colors"
                        style={{ backgroundColor: active ? `${C.blue}22` : 'transparent', color: active ? C.blue : C.textMuted }}>
                        <Icon size={16} />{item.label}
                      </button>
                    );
                  })}
                </nav>
              </div>
            ))}
          </div>
          <div className="pt-3 mt-3" style={{ borderTop: `1px solid ${C.border}` }}>
            <div className="px-3 mb-2 text-xs" style={{ color: C.text }}>{user.firstName} {user.lastName}</div>
            <button onClick={() => setShowChangePassword(true)} className="w-full flex items-center gap-2 px-3 py-2 rounded-lg text-xs" style={{ color: C.textMuted }}>
              <ShieldCheck size={14} /> Changer mon mot de passe
            </button>
            <button onClick={logout} className="w-full flex items-center gap-2 px-3 py-2 rounded-lg text-xs" style={{ color: C.textMuted }}>
              <LogOut size={14} /> Se déconnecter
            </button>
          </div>
        </aside>

        <main className="flex-1 p-6 overflow-x-hidden min-w-0">
          <header className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-6">
            <div className="flex items-center gap-3">
              <button className="md:hidden p-2 rounded-lg shrink-0" style={{ backgroundColor: C.card, border: `1px solid ${C.border}` }} onClick={() => setSidebarOpen(true)}>
                <Menu size={18} color={C.text} />
              </button>
              <div>
                <h1 className="text-xl font-semibold" style={{ color: C.text }}>{PAGE_TITLES[page]}</h1>
                <p className="text-xs" style={{ color: C.textMuted }}>{new Date().toLocaleDateString('fr-FR', { day: 'numeric', month: 'long', year: 'numeric' })} · Connecté en tant que {user.email} · ISO 9001 · 14001 · 45001</p>
              </div>
            </div>
            <div className="flex items-center gap-3">
              <button onClick={() => setThemeMode(themeMode === 'dark' ? 'light' : 'dark')} className="p-2 rounded-lg" style={{ backgroundColor: C.card, border: `1px solid ${C.border}` }} title="Changer de thème">
                {themeMode === 'dark' ? <Sun size={16} color={C.amber} /> : <Moon size={16} color={C.blue} />}
              </button>
              <div className="flex items-center gap-2 px-3 py-1.5 rounded-lg" style={{ backgroundColor: C.card, border: `1px solid ${C.border}` }}>
                <Bell size={16} color={C.amber} /><span className="text-xs" style={{ color: C.text }}>{capaStats.enRetard} action(s) CAPA en retard</span>
              </div>
            </div>
          </header>
          <PageComponent />
        </main>
      </div>
    </ThemeContext.Provider>
  );
}
